];

export const SystemTerminal: React.FC<SystemTerminalProps> = ({ isOpen, onClose }) => {
  const [logs, setLogs] = useState<string[]>([]);
  const [isMinimized, setIsMinimized] = useState(false);
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const interval = setInterval(() => {
      const msg = LOG_MESSAGES[Math.floor(Math.random() * LOG_MESSAGES.length)];
      const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
      setLogs(prev => [...prev.slice(-50), `[${timestamp}] ${msg}`]);
    }, 1500);

    return () => clearInterval(interval);
  }, [isOpen]);

  useEffect(() => {
    if (bottomRef.current) {
      bottomRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [logs]);

  if (!isOpen) return null;

  return (
    <div className={`fixed z-[99] transition-all duration-300 ease-in-out shadow-2xl border border-slate-800 bg-[#020617]/95 backdrop-blur-md overflow-hidden flex flex-col ${isMinimized ? 'bottom-4 right-20 w-72 h-12 rounded-t-xl' : 'bottom-0 left-0 right-0 h-64 border-t-primary-500/50'}`}>

      {/* Terminal Header */}
