interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export const AIAssistant: React.FC<{ code: string }> = ({ code }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: 'Hello! I am the CloudGuardian Copilot. How can I assist with your infrastructure security today?' }
  ]);
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Terraform HCL Context:\n${code}\n\nUser Question: ${userMsg}`,
        config: {
          systemInstruction: "You are the CloudGuardian AI Copilot, an expert in DevSecOps and cloud security (AWS/Azure/GCP). Provide concise, technical, and actionable security advice. Use markdown for code blocks.",
        }
      });

      const text = response.text || "I encountered an issue processing that request. Please try again.";
      setMessages(prev => [...prev, { role: 'assistant', content: text }]);
    } catch (error) {
      console.error("AI Assistant Error:", error);
      setMessages(prev => [...prev, { role: 'assistant', content: "Unable to reach the AI reasoning engine. Check your connection." }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <button 
        onClick={() => setIsOpen(true)}
        className="fixed bottom-6 right-6 w-14 h-14 bg-primary-600 hover:bg-primary-700 text-white rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-110 active:scale-95 z-[100] border border-primary-400/30"
      >
        <Sparkles size={24} className="animate-pulse" />
      </button>

      {isOpen && (
        <div className="fixed bottom-24 right-6 w-96 h-[520px] bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-[32px] shadow-[0_20px_80px_rgba(0,0,0,0.7)] flex flex-col z-[105] animate-in slide-in-from-bottom-10 duration-300 overflow-hidden">
          <header className="p-4 bg-slate-800/80 border-b border-white/5 flex justify-between items-center">
            <div className="flex items-center gap-2">
              <Bot className="text-primary-400" size={20} />
              <span className="font-black text-[10px] text-white uppercase tracking-widest">Security Copilot</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="text-slate-400 hover:text-white transition-colors p-1"><X size={18} /></button>
          </header>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
            {messages.map((msg, i) => (
              <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] p-4 rounded-2xl text-xs leading-relaxed ${
                  msg.role === 'user' 
                  ? 'bg-primary-600 text-white rounded-tr-none shadow-lg' 
                  : 'bg-slate-800/60 text-slate-300 rounded-tl-none border border-white/5'
                }`}>
                  {msg.content}
                </div>
              </div>
            ))}
            {loading && (
              <div className="flex justify-start">
                <div className="bg-slate-800 p-4 rounded-2xl rounded-tl-none border border-white/5 flex items-center gap-2">
                  <Loader2 className="animate-spin text-primary-500" size={14} />
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Reasoning...</span>
                </div>
              </div>
            )}
          </div>

          <form onSubmit={handleSendMessage} className="p-4 bg-slate-900/80 border-t border-white/5">
            <div className="relative">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ask about your infrastructure security..."
                className="w-full bg-slate-950/80 border border-white/10 rounded-2xl py-3 px-5 pr-12 text-xs text-white placeholder:text-slate-600 focus:outline-none focus:border-primary-500 transition-all shadow-inner"
              />
              <button type="submit" disabled={!input.trim()} className="absolute right-3 top-1/2 -translate-y-1/2 text-primary-500 hover:text-primary-400 disabled:opacity-30 p-1 transition-colors">
                <Send size={18} />
              </button>
            </div>
          </form>
        </div>
      )}
    </>
  );
};

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Database, Globe, Layers, X, Cpu, Radar,
  Maximize2, Zap, AlertTriangle, ShieldAlert, Wifi, Activity,
  ZoomIn, ZoomOut, Move
} from 'lucide-react';
import { Vulnerability, GraphNode, GraphEdge } from '../types';

// Simple Force Graph Simulation Types
interface SimNode extends GraphNode {
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const getCategoryColor = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; // Purple
    case 'storage': return '#eab308'; // Yellow
    case 'network': return '#3b82f6'; // Blue
    case 'security': return '#10b981'; // Emerald
    default: return '#64748b'; // Slate
  }
};

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'compute': return Cpu;
    case 'storage': return Database;
    case 'network': return Globe;
    case 'security': return Shield;
    default: return Layers;
  }
};

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
  focusedResourceId?: string | null;
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities, focusedResourceId }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [nodes, setNodes] = useState<SimNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);

  // Viewport State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Initialize Graph Data
  useEffect(() => {
    const { nodes: rawNodes, edges: rawEdges } = parseHclToGraph(code);

    // Enrich nodes with vulnerabilities and initial positions
    const simNodes: SimNode[] = rawNodes.map((n, i) => ({
      ...n,
      x: Math.random() * 800, // Random start for explosion effect
      y: Math.random() * 600,
      vx: 0,
      vy: 0,
      status: vulnerabilities.some(v => v.resource.includes(n.id)) ? 'risk' : 'healthy'
    }));

    setNodes(simNodes);
    setEdges(rawEdges);

    // Center view initially
    setPan({ x: window.innerWidth / 4, y: window.innerHeight / 6 });
  }, [code, vulnerabilities]);

  // Physics Engine
  useEffect(() => {
    let animationFrameId: number;

    const tick = () => {
      setNodes(prevNodes => {
        const newNodes = prevNodes.map(n => ({ ...n })); // Shallow copy

        // Constants
        const REPULSION = 15000;
        const SPRING = 0.05;
        const SPRING_LENGTH = 150;
        const DAMPING = 0.85;
        const CENTER_GRAVITY = 0.02;

        // 1. Repulsion (Nodes push apart)
        for (let i = 0; i < newNodes.length; i++) {
          for (let j = i + 1; j < newNodes.length; j++) {
            const n1 = newNodes[i];
            const n2 = newNodes[j];
            const dx = n1.x - n2.x;
            const dy = n1.y - n2.y;
            const distSq = dx * dx + dy * dy || 1;
            const force = REPULSION / distSq;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            n1.vx += fx;
            n1.vy += fy;
            n2.vx -= fx;
            n2.vy -= fy;
          }
        }

        // 2. Spring (Edges pull together)
        edges.forEach(edge => {
          const source = newNodes.find(n => n.id === edge.source);
          const target = newNodes.find(n => n.id === edge.target);
          if (source && target) {
            const dx = target.x - source.x;
            const dy = target.y - source.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const force = (dist - SPRING_LENGTH) * SPRING;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            source.vx += fx;
            source.vy += fy;
            target.vx -= fx;
            target.vy -= fy;
          }
        });

        // 3. Update Positions & Apply Damping + Gravity to center
        newNodes.forEach(n => {
          // Center gravity
          n.vx += (400 - n.x) * CENTER_GRAVITY;
          n.vy += (300 - n.y) * CENTER_GRAVITY;

          n.vx *= DAMPING;
          n.vy *= DAMPING;
          n.x += n.vx;
          n.y += n.vy;
        });

        return newNodes;
      });
      animationFrameId = requestAnimationFrame(tick);
    };

    animationFrameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animationFrameId);
  }, [edges]); // Re-run if edges change, but nodes are managed in state

  // Canvas Interactions
  const handleWheel = (e: React.WheelEvent) => {
    const newZoom = Math.min(Math.max(zoom - e.deltaY * 0.001, 0.2), 3);
    setZoom(newZoom);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if ((e.target as HTMLElement).tagName === 'svg') {
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (isDraggingCanvas) {
      setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  const handleMouseUp = () => setIsDraggingCanvas(false);

  // Blast Radius Calculation
  const getBlastRadius = (nodeId: string) => {
    const affected = new Set<string>();
    const stack = [nodeId];
    while (stack.length > 0) {
      const curr = stack.pop()!;
      if (!affected.has(curr)) {
        affected.add(curr);
        edges.filter(e => e.source === curr).forEach(e => stack.push(e.target));
      }
    }
    return affected;
  };

  const blastSet = selectedNodeId ? getBlastRadius(selectedNodeId) : new Set();
  const selectedNodeData = nodes.find(n => n.id === selectedNodeId);
  const selectedNodeVulns = vulnerabilities.filter(v => selectedNodeData && v.resource.includes(selectedNodeData.id));

  return (
    <div className="h-[calc(100vh-2rem)] flex flex-col p-6 overflow-hidden">

      {/* Main Canvas */}
      <div 
        ref={containerRef}
        className="flex-1 bg-[#020617] rounded-[48px] border border-white/5 relative overflow-hidden cursor-grab active:cursor-grabbing shadow-2xl"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {/* Header Overlay - Now inside relative container */}
        <div className="absolute top-8 left-8 z-20 pointer-events-none">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Activity className="text-primary-500 animate-pulse" size={14} />
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Live Topology Engine</span>
            </div>
            <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
              Infra <span className="text-primary-500">Universe</span>
            </h2>
          </div>
        </div>

        {/* Controls Overlay - Now inside relative container */}
        <div className="absolute top-8 right-8 z-20 flex gap-2">
          <button onClick={() => setZoom(z => Math.min(z + 0.2, 3))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomIn size={18}/></button>
          <button onClick={() => setZoom(z => Math.max(z - 0.2, 0.2))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomOut size={18}/></button>
          <button onClick={() => { setZoom(1); setPan({x: window.innerWidth/4, y: window.innerHeight/6}); }} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><Maximize2 size={18}/></button>
        </div>

        {/* Animated Background Grid */}
        <div className="absolute inset-0 opacity-[0.07] pointer-events-none" 
             style={{ 
               backgroundImage: 'linear-gradient(#4f46e5 1px, transparent 1px), linear-gradient(90deg, #4f46e5 1px, transparent 1px)', 
               backgroundSize: '50px 50px',
               transform: `scale(${zoom}) translate(${pan.x % 50}px, ${pan.y % 50}px)`
             }}>
        </div>

        <svg className="w-full h-full pointer-events-none">
          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
            {/* Edges */}
            {edges.map(edge => {
              const src = nodes.find(n => n.id === edge.source);
              const tgt = nodes.find(n => n.id === edge.target);
              if (!src || !tgt) return null;

              const isBlastPath = blastSet.has(edge.source) && blastSet.has(edge.target);
              const strokeColor = isBlastPath ? '#ef4444' : '#1e293b';
              const strokeWidth = isBlastPath ? 3 : 1;

              return (
                <g key={edge.id}>
                  <line 
                    x1={src.x} y1={src.y} x2={tgt.x} y2={tgt.y} 
                    stroke={strokeColor} 
                    strokeWidth={strokeWidth}
                    opacity={isBlastPath ? 1 : 0.4}
                  />
                  {/* Traffic Animation */}
                  <circle r={isBlastPath ? 3 : 2} fill={isBlastPath ? '#ef4444' : '#3b82f6'}>
                    <animateMotion 
                      dur={isBlastPath ? "0.5s" : "2s"} 
                      repeatCount="indefinite"
                      path={`M${src.x},${src.y} L${tgt.x},${tgt.y}`}
                    />
                  </circle>
                </g>
              );
            })}

            {/* Nodes (rendered as foreignObjects for HTML content or complex SVG) */}
            {nodes.map(node => {
              const isSelected = selectedNodeId === node.id;
              const isBlast = blastSet.has(node.id);
              const color = node.status === 'risk' ? '#ef4444' : getCategoryColor(node.data.category);
              const Icon = getCategoryIcon(node.data.category);

              return (
                <g 
                  key={node.id} 
                  transform={`translate(${node.x}, ${node.y})`}
                  className="pointer-events-auto cursor-pointer transition-all duration-300"
                  onClick={(e) => { e.stopPropagation(); setSelectedNodeId(node.id); }}
                >
                  {/* Blast Ripple */}
                  {(isBlast || node.status === 'risk') && (
                    <circle r="40" className="animate-ping opacity-20" fill={node.status === 'risk' ? '#ef4444' : '#3b82f6'} />
                  )}

                  {/* Node Body */}
                  <circle r="24" fill="#0f172a" stroke={isSelected ? '#fff' : color} strokeWidth={isSelected ? 3 : 2} className="transition-all" />

                  {/* Icon */}
                  <foreignObject x="-12" y="-12" width="24" height="24">
                    <div className="flex items-center justify-center w-full h-full text-white">
                      <Icon size={14} color={isSelected ? '#fff' : color} />
                    </div>
                  </foreignObject>

                  {/* Label */}
                  <text y="40" textAnchor="middle" fill={isSelected ? '#fff' : '#64748b'} fontSize="10" fontWeight="bold" className="uppercase tracking-widest pointer-events-none select-none">
                    {node.data.label}
                  </text>

                  {/* Risk Badge */}
                  {node.status === 'risk' && (
                    <g transform="translate(16, -16)">
                      <circle r="8" fill="#ef4444" />
                      <text x="0" y="3" textAnchor="middle" fill="white" fontSize="8" fontWeight="bold">!</text>
                    </g>
                  )}
                </g>
              );
            })}
          </g>
        </svg>

        {/* Selected Node Inspector Panel */}
        {selectedNodeData && (
          <div className="absolute top-24 right-8 w-80 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-right-10 duration-300 z-30">
             <div className="flex justify-between items-start mb-6">
                <div className={`p-3 rounded-2xl ${selectedNodeData.status === 'risk' ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                   {React.createElement(getCategoryIcon(selectedNodeData.data.category), { size: 24 })}
                </div>
                <button onClick={() => setSelectedNodeId(null)} className="p-2 hover:bg-white/5 rounded-xl text-slate-500 hover:text-white"><X size={18}/></button>
             </div>

             <div className="space-y-4">
                <div>
                   <h3 className="text-xl font-black text-white uppercase italic tracking-tighter">{selectedNodeData.data.label}</h3>
                   <span className="text-[10px] font-mono text-slate-500">{selectedNodeData.data.resource_type}</span>
                </div>

                <div className="p-4 bg-black/40 rounded-2xl border border-white/5 space-y-2">
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Connections</span>
                      <span className="text-white">{edges.filter(e => e.source === selectedNodeData.id || e.target === selectedNodeData.id).length}</span>
                   </div>
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Blast Radius</span>
                      <span className={blastSet.size > 1 ? "text-red-500" : "text-emerald-500"}>{blastSet.size} Nodes</span>
                   </div>
                </div>

                {selectedNodeVulns.length > 0 ? (
                   <div className="space-y-2">
                      <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                         <ShieldAlert size={12} /> Active Vulnerabilities
                      </h4>
                      {selectedNodeVulns.map(v => (
                         <div key={v.id} className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl">
                            <p className="text-[10px] font-bold text-red-400 leading-tight">{v.title}</p>
                         </div>
                      ))}
                   </div>
                ) : (
                   <div className="flex items-center gap-2 text-emerald-500 bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/20">
                      <ShieldAlert size={16} />
                      <span className="text-[10px] font-black uppercase">Secure Resource</span>
                   </div>
                )}

                <button className="w-full py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-black text-white uppercase tracking-widest transition-all">
                   View HCL Definition
                </button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Database, Globe, Layers, X, Cpu,
  Maximize2, ShieldAlert, Activity,
  ZoomIn, ZoomOut
} from 'lucide-react';
import { Vulnerability, GraphNode, GraphEdge } from '../types';

// Simple Force Graph Simulation Types
interface SimNode extends GraphNode {
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const getCategoryColor = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; // Purple
    case 'storage': return '#eab308'; // Yellow
    case 'network': return '#3b82f6'; // Blue
    case 'security': return '#10b981'; // Emerald
    default: return '#64748b'; // Slate
  }
};

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'compute': return Cpu;
    case 'storage': return Database;
    case 'network': return Globe;
    case 'security': return Shield;
    default: return Layers;
  }
};

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
  focusedResourceId?: string | null;
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities, focusedResourceId }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [nodes, setNodes] = useState<SimNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);

  // Viewport State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Interaction State
  const [isDraggingCanvas, setIsDraggingCanvas] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 }); // For canvas panning
  const dragNodeRef = useRef<{ id: string; offsetX: number; offsetY: number } | null>(null); // For node dragging

  // Initialize Graph Data
  useEffect(() => {
    const { nodes: rawNodes, edges: rawEdges } = parseHclToGraph(code);

    // Enrich nodes with vulnerabilities and initial positions
    const simNodes: SimNode[] = rawNodes.map((n, i) => ({
      ...n,
      x: Math.random() * 800, 
      y: Math.random() * 600,
      vx: 0,
      vy: 0,
      status: vulnerabilities.some(v => v.resource.includes(n.id)) ? 'risk' : 'healthy'
    }));

    setNodes(simNodes);
    setEdges(rawEdges);

    // Center view initially
    setPan({ x: window.innerWidth / 4, y: window.innerHeight / 6 });
  }, [code, vulnerabilities]);

  // Physics Engine
  useEffect(() => {
    let animationFrameId: number;

    const tick = () => {
      setNodes(prevNodes => {
        const newNodes = prevNodes.map(n => ({ ...n })); // Shallow copy

        // Constants
        const REPULSION = 8000;
        const SPRING = 0.04;
        const SPRING_LENGTH = 180;
        const DAMPING = 0.85;
        const CENTER_GRAVITY = 0.01;

        // 1. Repulsion (Nodes push apart)
        for (let i = 0; i < newNodes.length; i++) {
          for (let j = i + 1; j < newNodes.length; j++) {
            const n1 = newNodes[i];
            const n2 = newNodes[j];
            const dx = n1.x - n2.x;
            const dy = n1.y - n2.y;
            const distSq = dx * dx + dy * dy || 1;
            const force = REPULSION / distSq;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            n1.vx += fx;
            n1.vy += fy;
            n2.vx -= fx;
            n2.vy -= fy;
          }
        }

        // 2. Spring (Edges pull together)
        edges.forEach(edge => {
          const source = newNodes.find(n => n.id === edge.source);
          const target = newNodes.find(n => n.id === edge.target);
          if (source && target) {
            const dx = target.x - source.x;
            const dy = target.y - source.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const force = (dist - SPRING_LENGTH) * SPRING;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            source.vx += fx;
            source.vy += fy;
            target.vx -= fx;
            target.vy -= fy;
          }
        });

        // 3. Update Positions & Apply Damping
        newNodes.forEach(n => {
          // If this node is being dragged, it is controlled by the mouse (via handleMouseMove updating state directly? 
          // No, to avoid fighting, we usually skip physics update for dragged node or reset velocity).
          // However, since handleMouseMove updates the state asynchronously, we might fight.
          // Better strategy: The physics loop doesn't update the dragged node's position, but applies velocity to others.

          if (dragNodeRef.current && n.id === dragNodeRef.current.id) {
             // Zero out velocity so it doesn't shoot away when released
             n.vx = 0; 
             n.vy = 0;
             // Position is effectively pinned by the mouse handler update
          } else {
             // Center gravity
             n.vx += (400 - n.x) * CENTER_GRAVITY;
             n.vy += (300 - n.y) * CENTER_GRAVITY;

             n.vx *= DAMPING;
             n.vy *= DAMPING;
             n.x += n.vx;
             n.y += n.vy;
          }
        });

        return newNodes;
      });
      animationFrameId = requestAnimationFrame(tick);
    };

    animationFrameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animationFrameId);
  }, [edges]); 

  // Canvas Interactions
  const handleWheel = (e: React.WheelEvent) => {
    const newZoom = Math.min(Math.max(zoom - e.deltaY * 0.001, 0.2), 3);
    setZoom(newZoom);
  };

  const getGraphCoordinates = (clientX: number, clientY: number) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    return {
      x: (clientX - rect.left - pan.x) / zoom,
      y: (clientY - rect.top - pan.y) / zoom
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Check if we clicked a node
    const nodeElement = (e.target as Element).closest('[data-node-id]');

    if (nodeElement) {
      e.stopPropagation();
      const nodeId = nodeElement.getAttribute('data-node-id');
      if (nodeId) {
        const node = nodes.find(n => n.id === nodeId);
        if (node) {
          const coords = getGraphCoordinates(e.clientX, e.clientY);
          dragNodeRef.current = {
            id: nodeId,
            offsetX: node.x - coords.x,
            offsetY: node.y - coords.y
          };
          setSelectedNodeId(nodeId);
        }
      }
    } else {
      // Pan Canvas
      setIsDraggingCanvas(true);
      setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (dragNodeRef.current) {
      // Move Node
      const coords = getGraphCoordinates(e.clientX, e.clientY);
      const newX = coords.x + dragNodeRef.current.offsetX;
      const newY = coords.y + dragNodeRef.current.offsetY;

      setNodes(prev => prev.map(n => 
        n.id === dragNodeRef.current!.id 
          ? { ...n, x: newX, y: newY, vx: 0, vy: 0 } 
          : n
      ));
    } else if (isDraggingCanvas) {
      // Pan Canvas
      setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
    }
  };

  const handleMouseUp = () => {
    dragNodeRef.current = null;
    setIsDraggingCanvas(false);
  };

  // Blast Radius Calculation
  const getBlastRadius = (nodeId: string) => {
    const affected = new Set<string>();
    const stack = [nodeId];
    while (stack.length > 0) {
      const curr = stack.pop()!;
      if (!affected.has(curr)) {
        affected.add(curr);
        edges.filter(e => e.source === curr).forEach(e => stack.push(e.target));
      }
    }
    return affected;
  };

  const blastSet = selectedNodeId ? getBlastRadius(selectedNodeId) : new Set();
  const selectedNodeData = nodes.find(n => n.id === selectedNodeId);
  const selectedNodeVulns = vulnerabilities.filter(v => selectedNodeData && v.resource.includes(selectedNodeData.id));

  return (
    <div className="h-[calc(100vh-2rem)] flex flex-col p-6 overflow-hidden">

      {/* Main Canvas */}
      <div 
        ref={containerRef}
        className={`flex-1 bg-[#020617] rounded-[48px] border border-white/5 relative overflow-hidden shadow-2xl ${isDraggingCanvas || dragNodeRef.current ? 'cursor-grabbing' : 'cursor-grab'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {/* Header Overlay */}
        <div className="absolute top-8 left-8 z-20 pointer-events-none">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Activity className="text-primary-500 animate-pulse" size={14} />
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Live Topology Engine</span>
            </div>
            <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
              Infra <span className="text-primary-500">Universe</span>
            </h2>
          </div>
        </div>

        {/* Controls Overlay */}
        <div className="absolute top-8 right-8 z-20 flex gap-2">
          <button onClick={() => setZoom(z => Math.min(z + 0.2, 3))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomIn size={18}/></button>
          <button onClick={() => setZoom(z => Math.max(z - 0.2, 0.2))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomOut size={18}/></button>
          <button onClick={() => { setZoom(1); setPan({x: window.innerWidth/4, y: window.innerHeight/6}); }} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><Maximize2 size={18}/></button>
        </div>

        {/* Animated Background Grid */}
        <div className="absolute inset-0 opacity-[0.07] pointer-events-none" 
             style={{ 
               backgroundImage: 'linear-gradient(#4f46e5 1px, transparent 1px), linear-gradient(90deg, #4f46e5 1px, transparent 1px)', 
               backgroundSize: '50px 50px',
               transform: `scale(${zoom}) translate(${pan.x % 50}px, ${pan.y % 50}px)`
             }}>
        </div>

        <svg className="w-full h-full pointer-events-none">
          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
            {/* Edges */}
            {edges.map(edge => {
              const src = nodes.find(n => n.id === edge.source);
              const tgt = nodes.find(n => n.id === edge.target);
              if (!src || !tgt) return null;

              const isBlastPath = blastSet.has(edge.source) && blastSet.has(edge.target);
              const strokeColor = isBlastPath ? '#ef4444' : '#1e293b';
              const strokeWidth = isBlastPath ? 3 : 1;

              return (
                <g key={edge.id}>
                  <line 
                    x1={src.x} y1={src.y} x2={tgt.x} y2={tgt.y} 
                    stroke={strokeColor} 
                    strokeWidth={strokeWidth}
                    opacity={isBlastPath ? 1 : 0.4}
                  />
                  {/* Traffic Animation */}
                  <circle r={isBlastPath ? 3 : 2} fill={isBlastPath ? '#ef4444' : '#3b82f6'}>
                    <animateMotion 
                      dur={isBlastPath ? "0.5s" : "2s"} 
                      repeatCount="indefinite"
                      path={`M${src.x},${src.y} L${tgt.x},${tgt.y}`}
                    />
                  </circle>
                </g>
              );
            })}

            {/* Nodes */}
            {nodes.map(node => {
              const isSelected = selectedNodeId === node.id;
              const isBlast = blastSet.has(node.id);
              const color = node.status === 'risk' ? '#ef4444' : getCategoryColor(node.data.category);
              const Icon = getCategoryIcon(node.data.category);

              return (
                <g 
                  key={node.id} 
                  data-node-id={node.id}
                  transform={`translate(${node.x}, ${node.y})`}
                  className="pointer-events-auto cursor-pointer transition-colors duration-300"
                >
                  {/* Interaction Hit Area (Larger than visual) */}
                  <circle r="30" fill="transparent" />

                  {/* Blast Ripple */}
                  {(isBlast || node.status === 'risk') && (
                    <circle r="40" className="animate-ping opacity-20" fill={node.status === 'risk' ? '#ef4444' : '#3b82f6'} />
                  )}

                  {/* Node Body */}
                  <circle r="24" fill="#0f172a" stroke={isSelected ? '#fff' : color} strokeWidth={isSelected ? 3 : 2} className="transition-all" />

                  {/* Icon */}
                  <foreignObject x="-12" y="-12" width="24" height="24" className="pointer-events-none">
                    <div className="flex items-center justify-center w-full h-full text-white">
                      <Icon size={14} color={isSelected ? '#fff' : color} />
                    </div>
                  </foreignObject>

                  {/* Label */}
                  <text y="40" textAnchor="middle" fill={isSelected ? '#fff' : '#64748b'} fontSize="10" fontWeight="bold" className="uppercase tracking-widest pointer-events-none select-none">
                    {node.data.label}
                  </text>

                  {/* Risk Badge */}
                  {node.status === 'risk' && (
                    <g transform="translate(16, -16)">
                      <circle r="8" fill="#ef4444" />
                      <text x="0" y="3" textAnchor="middle" fill="white" fontSize="8" fontWeight="bold">!</text>
                    </g>
                  )}
                </g>
              );
            })}
          </g>
        </svg>

        {/* Selected Node Inspector Panel */}
        {selectedNodeData && (
          <div className="absolute top-24 right-8 w-80 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-right-10 duration-300 z-30 pointer-events-auto">
             <div className="flex justify-between items-start mb-6">
                <div className={`p-3 rounded-2xl ${selectedNodeData.status === 'risk' ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                   {React.createElement(getCategoryIcon(selectedNodeData.data.category), { size: 24 })}
                </div>
                <button onClick={() => setSelectedNodeId(null)} className="p-2 hover:bg-white/5 rounded-xl text-slate-500 hover:text-white"><X size={18}/></button>
             </div>

             <div className="space-y-4">
                <div>
                   <h3 className="text-xl font-black text-white uppercase italic tracking-tighter">{selectedNodeData.data.label}</h3>
                   <span className="text-[10px] font-mono text-slate-500">{selectedNodeData.data.resource_type}</span>
                </div>

                <div className="p-4 bg-black/40 rounded-2xl border border-white/5 space-y-2">
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Connections</span>
                      <span className="text-white">{edges.filter(e => e.source === selectedNodeData.id || e.target === selectedNodeData.id).length}</span>
                   </div>
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Blast Radius</span>
                      <span className={blastSet.size > 1 ? "text-red-500" : "text-emerald-500"}>{blastSet.size} Nodes</span>
                   </div>
                </div>

                {selectedNodeVulns.length > 0 ? (
                   <div className="space-y-2">
                      <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                         <ShieldAlert size={12} /> Active Vulnerabilities
                      </h4>
