import { SentinelMap } from './pages/SentinelMap';
import { KnowledgeBase } from './pages/KnowledgeBase';
import { AuditorBanner } from './components/AuditorBanner';
import { View, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun, ScanStatus, Project } from './types';
import { API } from './services/backend';
import { dbService } from './services/dbService';
import { Loader2, CheckCircle2, X } from 'lucide-react';

const DEFAULT_CODE = `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
  acl    = "public-read"
}

resource "aws_security_group" "ssh_access" {
  name        = "ssh_open"
  description = "Permit SSH from anywhere"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
`;

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(() => localStorage.getItem('cg_auth') === 'true');
  const [isInitializing, setIsInitializing] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [isAuditorMode, setIsAuditorMode] = useState(false);
  const [currentView, setCurrentView] = useState<View>('dashboard');

  const [projects, setProjects] = useState<Project[]>([]);
  const [activeProjectId, setActiveProjectId] = useState<string | null>(localStorage.getItem('cg_active_project'));

  const [terraformCode, setTerraformCode] = useState(DEFAULT_CODE);
  const [activeIncident, setActiveIncident] = useState<Vulnerability | null>(null);

  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  const [timelineEvents, setTimelineEvents] = useState<TimelineEvent[]>([]);
  const [drifts, setDrifts] = useState<DriftItem[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [pipelineRuns, setPipelineRuns] = useState<PipelineRun[]>([]);

  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLiveAssistantOpen, setIsLiveAssistantOpen] = useState(false);
  const [isTerminalOpen, setIsTerminalOpen] = useState(false);
  const [isMobileSidebarOpen, setIsMobileSidebarOpen] = useState(false);

  // Command Palette State
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  const activeProject = useMemo(() => projects.find(p => p.id === activeProjectId), [projects, activeProjectId]);
  const securityScore = useMemo(() => API.calculateScore(vulnerabilities, drifts), [vulnerabilities, drifts]);

  useEffect(() => {
    if (isAuthenticated) {
      loadInitialData();
    } else {
      setIsInitializing(false);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (activeProjectId) {
      localStorage.setItem('cg_active_project', activeProjectId);
      if (activeProjectId === 'proj-2') {
         setVulnerabilities(v => v.length > 0 ? v : []);
      }
    }
  }, [activeProjectId]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsPaletteOpen(prev => !prev);
      }
      if ((e.metaKey || e.ctrlKey) && e.key === 'j') {
        e.preventDefault();
        setIsTerminalOpen(prev => !prev);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const loadInitialData = async () => {
    try {
      const [timeline, initialPolicies, initialVulns, initialDrifts, initialProjects] = await Promise.all([
        API.getTimeline(), API.getPolicies(), API.getVulnerabilities(), API.fetchCloudDrifts(), dbService.getProjects()
      ]);
      setTimelineEvents(timeline || []);
      setPolicies(initialPolicies || []);
      setVulnerabilities(initialVulns || []);
      setDrifts(initialDrifts || []);
      setProjects(initialProjects || []);

      if (!activeProjectId && initialProjects.length > 0) {
        setActiveProjectId(initialProjects[0].id);
      }
      setIsInitializing(false);
    } catch (e) { 
      setIsInitializing(false); 
    }
  };

  const showNotification = (message: string, type: 'success' | 'error' = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  const onScanFinished = (vulns: Vulnerability[]) => {
    setVulnerabilities(vulns);
    showNotification(`Scan concluído no ambiente ${activeProject?.name}.`);
    API.logEvent({
      type: 'SCAN', title: 'Relatório Gerado',
      description: `Ambiente ${activeProject?.name} analisado. ${vulns.length} riscos encontrados.`,
      severity: vulns.length > 0 ? Severity.HIGH : Severity.LOW
    }).then(evt => setTimelineEvents(prev => [evt, ...prev]));
  };

  const handleApplyFix = async (vulnId: string, newSnippet: string) => {
    const targetVuln = vulnerabilities.find(v => v.id === vulnId);
    if (!targetVuln) return;
    const resourceParts = targetVuln.resource.split('.');
    const regex = new RegExp(`resource\\s+"${resourceParts[0]}"\\s+"${resourceParts[1]}"\\s*{[\\s\\S]*?}`, 'g');
    if (regex.test(terraformCode)) {
      setTerraformCode(terraformCode.replace(regex, newSnippet));
      const updatedVulns = vulnerabilities.filter(v => v.id !== vulnId);
      setVulnerabilities(updatedVulns);
      await API.setVulnerabilities(updatedVulns);
      showNotification("Patch aplicado com sucesso via IA.");
    }
  };

  const handleResolveIncident = (inc: Vulnerability, logs: string[]) => {
    setVulnerabilities(v => v.map(vi => vi.id === inc.id ? {...inc, status: ScanStatus.RESOLVED, containmentLog: logs} : vi));
    API.logEvent({
      type: 'INCIDENT',
      title: 'Incidente Resolvido',
      description: `Resposta ativa concluída para ${inc.title}. Relatório RCA gerado.`,
      severity: Severity.LOW
    });
    setCurrentView('post-mortem');
  };

  if (isInitializing) return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
      <Loader2 className="text-primary-500 animate-spin" size={64} />
      <span className="text-slate-500 font-black uppercase text-[10px] tracking-[0.4em]">Readying Guardian Core...</span>
    </div>
  );

  if (!isAuthenticated) {
    if (showLogin) return <Login onLogin={() => { setIsAuthenticated(true); loadInitialData(); }} />;
    return <LandingPage onStart={() => setShowLogin(true)} onViewDemo={() => { setIsAuthenticated(true); loadInitialData(); }} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-950 text-slate-200 font-sans overflow-hidden">
      <CommandPalette 
        isOpen={isPaletteOpen} 
        onClose={() => setIsPaletteOpen(false)} 
        onNavigate={setCurrentView}
        actions={{
          toggleAuditor: () => { setIsAuditorMode(prev => !prev); showNotification("Modo Auditor Alternado"); },
          toggleLive: () => setIsLiveAssistantOpen(true),
          logout: () => { setIsAuthenticated(false); localStorage.removeItem('cg_auth'); }
        }}
      />

      <SystemTerminal isOpen={isTerminalOpen} onClose={() => setIsTerminalOpen(false)} />

      {/* Mobile Sidebar Overlay */}
      {isMobileSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[140] lg:hidden"
          onClick={() => setIsMobileSidebarOpen(false)}
        ></div>
      )}

      <Sidebar 
        currentView={currentView} 
        onNavigate={(view) => { setCurrentView(view); setIsMobileSidebarOpen(false); }} 
        onLogout={() => { setIsAuthenticated(false); localStorage.removeItem('cg_auth'); }} 
        isAuditorMode={isAuditorMode}
        hasActiveIncident={!!activeIncident && activeIncident.status !== ScanStatus.RESOLVED}
        isMobileOpen={isMobileSidebarOpen}
      />

      <main className={`flex-1 min-h-screen relative flex flex-col overflow-hidden transition-all duration-300 ${isMobileSidebarOpen ? 'lg:ml-64 blur-sm lg:blur-none' : 'lg:ml-64'}`}>
        {isAuditorMode && <AuditorBanner />}
        <Header 
          isAuditor={isAuditorMode} 
          onToggleAuditor={() => setIsAuditorMode(!isAuditorMode)} 
          notificationsCount={vulnerabilities.length}
          onToggleLiveAssistant={() => setIsLiveAssistantOpen(true)}
          isLiveActive={isLiveAssistantOpen}
          activeProjectId={activeProjectId}
          projects={projects}
          onProjectChange={setActiveProjectId}
          onOpenPalette={() => setIsPaletteOpen(true)}
          onToggleTerminal={() => setIsTerminalOpen(prev => !prev)}
          isTerminalOpen={isTerminalOpen}
          onMobileMenuClick={() => setIsMobileSidebarOpen(true)}
        />
        {toast && (
          <div className="fixed top-20 right-8 z-[110] px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-4 animate-in slide-in-from-top-10 border backdrop-blur-md bg-slate-900/90 border-primary-500/20">
            {toast.type === 'success' ? <CheckCircle2 size={20} className="text-emerald-500" /> : <X size={20} className="text-red-500" />}
            <span className="text-[10px] font-black uppercase tracking-widest">{toast.message}</span>
          </div>
        )}
        <div className="flex-1 overflow-y-auto custom-scrollbar">
          {currentView === 'dashboard' && <Dashboard vulnerabilities={vulnerabilities} drifts={drifts} score={securityScore} timeline={timelineEvents} onNavigate={setCurrentView} policies={policies} runs={pipelineRuns} />}
          {currentView === 'sentinel' && <SentinelMap />}
          {currentView === 'knowledge-base' && <KnowledgeBase />}
          {currentView === 'inventory' && <Inventory />}
          {currentView === 'scanner' && <Scanner code={terraformCode} onCodeChange={setTerraformCode} onScanComplete={onScanFinished} vulnerabilities={vulnerabilities} onApplyFix={handleApplyFix} onSimulateBlast={(v) => { setActiveIncident(v); setCurrentView('war-room'); }} />}
          {currentView === 'organization' && <Organization onNavigate={setCurrentView} onNotify={showNotification} />}
          {currentView === 'graph' && <Graph code={terraformCode} vulnerabilities={vulnerabilities} />}
          {currentView === 'compliance' && <Compliance vulnerabilities={vulnerabilities} />}
          {currentView === 'drift' && <Drift isAuditorMode={isAuditorMode} />}
          {currentView === 'policies' && <PolicyManager policies={policies} setPolicies={setPolicies} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'policy-forge' && <PolicyForge onNotify={showNotification} />}
          {currentView === 'cicd' && <PipelineInsights runs={pipelineRuns} setRuns={setPipelineRuns} onNotify={showNotification} onTimeline={(evt) => setTimelineEvents(prev => [evt, ...prev])} />}
          {currentView === 'finops' && <FinOps vulnerabilities={vulnerabilities} />}
          {currentView === 'automation' && <AutomationHub />}
          {currentView === 'sales-playbook' && <SalesPlaybook />}
          {currentView === 'roadmap' && <Roadmap />}
          {currentView === 'report' && <ProjectReport score={securityScore} vulnerabilities={vulnerabilities} />}
          {currentView === 'timeline' && <Timeline events={timelineEvents} />}
          {currentView === 'settings' && <Settings />}
          {currentView === 'security-tests' && <SecurityTesting />}
          {currentView === 'war-room' && <WarRoom incident={activeIncident} onNotify={showNotification} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onResolve={handleResolveIncident} />}
          {currentView === 'post-mortem' && <PostMortem incident={activeIncident} onClose={() => { setActiveIncident(null); setCurrentView('dashboard'); }} onNotify={showNotification} />}
        </div>
        {isLiveAssistantOpen && <LiveAssistant codeContext={terraformCode} onClose={() => setIsLiveAssistantOpen(false)} />}
        <AIAssistant code={terraformCode} />
      </main>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { parseHclToGraph } from '../services/engine';
import { 
  Shield, Database, Globe, Layers, X, Cpu,
  Maximize2, ShieldAlert, Activity,
  ZoomIn, ZoomOut
} from 'lucide-react';
import { Vulnerability, GraphNode, GraphEdge } from '../types';

// Simple Force Graph Simulation Types
interface SimNode extends GraphNode {
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const getCategoryColor = (category: string) => {
  switch (category) {
    case 'compute': return '#a855f7'; // Purple
    case 'storage': return '#eab308'; // Yellow
    case 'network': return '#3b82f6'; // Blue
    case 'security': return '#10b981'; // Emerald
    default: return '#64748b'; // Slate
  }
};

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'compute': return Cpu;
    case 'storage': return Database;
    case 'network': return Globe;
    case 'security': return Shield;
    default: return Layers;
  }
};

interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
  focusedResourceId?: string | null;
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities, focusedResourceId }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [nodes, setNodes] = useState<SimNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);

  // Viewport State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Interaction Refs (Critical for smooth 60fps loop)
  const isDraggingCanvas = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const draggedNode = useRef<{ id: string; x: number; y: number } | null>(null);

  // Initialize Graph Data
  useEffect(() => {
    const { nodes: rawNodes, edges: rawEdges } = parseHclToGraph(code);

    // Enrich nodes with vulnerabilities and initial positions
    const simNodes: SimNode[] = rawNodes.map((n, i) => ({
      ...n,
      x: Math.random() * 800, 
      y: Math.random() * 600,
      vx: 0,
      vy: 0,
      status: vulnerabilities.some(v => v.resource.includes(n.id)) ? 'risk' : 'healthy'
    }));

    setNodes(simNodes);
    setEdges(rawEdges);

    // Center view initially
    setPan({ x: window.innerWidth / 4, y: window.innerHeight / 6 });
  }, [code, vulnerabilities]);

  // Physics Engine
  useEffect(() => {
    let animationFrameId: number;

    const tick = () => {
      setNodes(prevNodes => {
        const newNodes = prevNodes.map(n => ({ ...n })); // Shallow copy

        // Constants
        const REPULSION = 6000;
        const SPRING = 0.02;
        const SPRING_LENGTH = 200;
        const DAMPING = 0.90; // Higher damping for 'floaty' space feel
        const CENTER_GRAVITY = 0.002; // Very low gravity to keep them "loose"

        // 1. Repulsion (Nodes push apart)
        for (let i = 0; i < newNodes.length; i++) {
          for (let j = i + 1; j < newNodes.length; j++) {
            const n1 = newNodes[i];
            const n2 = newNodes[j];
            const dx = n1.x - n2.x;
            const dy = n1.y - n2.y;
            const distSq = dx * dx + dy * dy || 1;
            const force = REPULSION / distSq;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            n1.vx += fx;
            n1.vy += fy;
            n2.vx -= fx;
            n2.vy -= fy;
          }
        }

        // 2. Spring (Edges pull together)
        edges.forEach(edge => {
          const source = newNodes.find(n => n.id === edge.source);
          const target = newNodes.find(n => n.id === edge.target);
          if (source && target) {
            const dx = target.x - source.x;
            const dy = target.y - source.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const force = (dist - SPRING_LENGTH) * SPRING;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            source.vx += fx;
            source.vy += fy;
            target.vx -= fx;
            target.vy -= fy;
          }
        });

        // 3. Update Positions & Apply Damping
        newNodes.forEach(n => {
          // If node is being dragged, lock it to mouse position ref
          if (draggedNode.current && n.id === draggedNode.current.id) {
             n.x = draggedNode.current.x;
             n.y = draggedNode.current.y;
             n.vx = 0;
             n.vy = 0;
          } else {
             // Weak center gravity just to prevent them from drifting to infinity
             n.vx += (400 - n.x) * CENTER_GRAVITY;
             n.vy += (300 - n.y) * CENTER_GRAVITY;

             n.vx *= DAMPING;
             n.vy *= DAMPING;
             n.x += n.vx;
             n.y += n.vy;
          }
        });

        return newNodes;
      });
      animationFrameId = requestAnimationFrame(tick);
    };

    animationFrameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animationFrameId);
  }, [edges]); 

  // Canvas Interactions
  const handleWheel = (e: React.WheelEvent) => {
    const newZoom = Math.min(Math.max(zoom - e.deltaY * 0.001, 0.2), 3);
    setZoom(newZoom);
  };

  const getGraphCoordinates = (clientX: number, clientY: number) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    return {
      x: (clientX - rect.left - pan.x) / zoom,
      y: (clientY - rect.top - pan.y) / zoom
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Check if we clicked a node
    const nodeElement = (e.target as Element).closest('[data-node-id]');

    if (nodeElement) {
      e.stopPropagation();
      const nodeId = nodeElement.getAttribute('data-node-id');
      if (nodeId) {
        const node = nodes.find(n => n.id === nodeId);
        if (node) {
          const coords = getGraphCoordinates(e.clientX, e.clientY);
          draggedNode.current = { id: nodeId, x: node.x, y: node.y }; 
          setSelectedNodeId(nodeId);
        }
      }
    } else {
      // Pan Canvas
      isDraggingCanvas.current = true;
      dragStart.current = { x: e.clientX - pan.x, y: e.clientY - pan.y };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggedNode.current) {
      // Update the REF only, not state. The tick loop will pick it up.
      const coords = getGraphCoordinates(e.clientX, e.clientY);
      draggedNode.current.x = coords.x;
      draggedNode.current.y = coords.y;
    } else if (isDraggingCanvas.current) {
      // Panning updates React state immediately as it affects transform style
      setPan({ x: e.clientX - dragStart.current.x, y: e.clientY - dragStart.current.y });
    }
  };

  const handleMouseUp = () => {
    draggedNode.current = null;
    isDraggingCanvas.current = false;
  };

  // Blast Radius Calculation
  const getBlastRadius = (nodeId: string) => {
    const affected = new Set<string>();
    const stack = [nodeId];
    while (stack.length > 0) {
      const curr = stack.pop()!;
      if (!affected.has(curr)) {
        affected.add(curr);
        edges.filter(e => e.source === curr).forEach(e => stack.push(e.target));
      }
    }
    return affected;
  };

  const blastSet = selectedNodeId ? getBlastRadius(selectedNodeId) : new Set();
  const selectedNodeData = nodes.find(n => n.id === selectedNodeId);
  const selectedNodeVulns = vulnerabilities.filter(v => selectedNodeData && v.resource.includes(selectedNodeData.id));

  return (
    <div className="h-[calc(100vh-2rem)] flex flex-col p-6 overflow-hidden">

      {/* Main Canvas */}
      <div 
        ref={containerRef}
        className="flex-1 bg-[#020617] rounded-[48px] border border-white/5 relative overflow-hidden shadow-2xl cursor-grab active:cursor-grabbing"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        {/* Header Overlay */}
        <div className="absolute top-8 left-8 z-30 pointer-events-none">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Activity className="text-primary-500 animate-pulse" size={14} />
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Live Topology Engine</span>
            </div>
            <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
              Infra <span className="text-primary-500">Universe</span>
            </h2>
          </div>
        </div>

        {/* Controls Overlay */}
        <div className="absolute top-8 right-8 z-30 flex gap-2">
          <button onClick={() => setZoom(z => Math.min(z + 0.2, 3))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomIn size={18}/></button>
          <button onClick={() => setZoom(z => Math.max(z - 0.2, 0.2))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomOut size={18}/></button>
          <button onClick={() => { setZoom(1); setPan({x: window.innerWidth/4, y: window.innerHeight/6}); }} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><Maximize2 size={18}/></button>
        </div>

        {/* Animated Background Grid */}
        <div className="absolute inset-0 opacity-[0.07] pointer-events-none" 
             style={{ 
               backgroundImage: 'linear-gradient(#4f46e5 1px, transparent 1px), linear-gradient(90deg, #4f46e5 1px, transparent 1px)', 
               backgroundSize: '50px 50px',
               transform: `scale(${zoom}) translate(${pan.x % 50}px, ${pan.y % 50}px)`
             }}>
        </div>

        <svg className="w-full h-full pointer-events-none">
          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
            {/* Edges */}
            {edges.map(edge => {
              const src = nodes.find(n => n.id === edge.source);
              const tgt = nodes.find(n => n.id === edge.target);
              if (!src || !tgt) return null;

              const isBlastPath = blastSet.has(edge.source) && blastSet.has(edge.target);
              // Dim unrelated edges if a node is selected
              const opacity = selectedNodeId ? (isBlastPath ? 1 : 0.1) : 0.4;
              const strokeColor = isBlastPath ? '#ef4444' : '#1e293b';
              const strokeWidth = isBlastPath ? 3 : 1;

              return (
                <g key={edge.id} className="transition-all duration-300">
                  <line 
                    x1={src.x} y1={src.y} x2={tgt.x} y2={tgt.y} 
                    stroke={strokeColor} 
                    strokeWidth={strokeWidth}
                    opacity={opacity}
                  />
                  {/* Traffic Animation - Only active on blast path when selected */}
                  {(isBlastPath || !selectedNodeId) && (
                    <circle r={isBlastPath ? 3 : 2} fill={isBlastPath ? '#ef4444' : '#3b82f6'}>
                      <animateMotion 
                        dur={isBlastPath ? "0.5s" : "2s"} 
                        repeatCount="indefinite"
                        path={`M${src.x},${src.y} L${tgt.x},${tgt.y}`}
                      />
                    </circle>
                  )}
                </g>
              );
            })}

            {/* Nodes */}
            {nodes.map(node => {
              const isSelected = selectedNodeId === node.id;
              const isBlast = blastSet.has(node.id);
              // Dim unrelated nodes
              const isDimmed = selectedNodeId && !isBlast;

              const color = node.status === 'risk' ? '#ef4444' : getCategoryColor(node.data.category);
              const Icon = getCategoryIcon(node.data.category);

              return (
                <g 
                  key={node.id} 
                  data-node-id={node.id}
                  transform={`translate(${node.x}, ${node.y})`}
                  className={`pointer-events-auto cursor-pointer transition-all duration-300 ${isDimmed ? 'opacity-20' : 'opacity-100'}`}
                >
                  {/* Interaction Hit Area (Larger than visual) */}
                  <circle r="30" fill="transparent" />

                  {/* Blast Ripple / Risk Ripple */}
                  {(isBlast || node.status === 'risk') && !isDimmed && (
                    <circle r="40" className="animate-ping opacity-20" fill={node.status === 'risk' ? '#ef4444' : '#3b82f6'} />
                  )}

                  {/* Node Body */}
                  <circle r="24" fill="#0f172a" stroke={isSelected ? '#fff' : color} strokeWidth={isSelected ? 3 : 2} className="transition-all" />

                  {/* Icon */}
                  <foreignObject x="-12" y="-12" width="24" height="24" className="pointer-events-none">
                    <div className="flex items-center justify-center w-full h-full text-white">
                      <Icon size={14} color={isSelected ? '#fff' : color} />
                    </div>
                  </foreignObject>

                  {/* Label */}
                  <text y="40" textAnchor="middle" fill={isSelected ? '#fff' : '#64748b'} fontSize="10" fontWeight="bold" className="uppercase tracking-widest pointer-events-none select-none">
                    {node.data.label}
                  </text>

                  {/* Risk Badge */}
                  {node.status === 'risk' && (
                    <g transform="translate(16, -16)">
                      <circle r="8" fill="#ef4444" />
                      <text x="0" y="3" textAnchor="middle" fill="white" fontSize="8" fontWeight="bold">!</text>
                    </g>
                  )}
                </g>
              );
            })}
          </g>
        </svg>

        {/* Selected Node Inspector Panel */}
        {selectedNodeData && (
          <div className="absolute top-24 right-8 w-80 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-right-10 duration-300 z-30 pointer-events-auto">
             <div className="flex justify-between items-start mb-6">
                <div className={`p-3 rounded-2xl ${selectedNodeData.status === 'risk' ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                   {React.createElement(getCategoryIcon(selectedNodeData.data.category), { size: 24 })}
                </div>
                <button onClick={() => setSelectedNodeId(null)} className="p-2 hover:bg-white/5 rounded-xl text-slate-500 hover:text-white"><X size={18}/></button>
             </div>

             <div className="space-y-4">
                <div>
                   <h3 className="text-xl font-black text-white uppercase italic tracking-tighter">{selectedNodeData.data.label}</h3>
                   <span className="text-[10px] font-mono text-slate-500">{selectedNodeData.data.resource_type}</span>
                </div>

                <div className="p-4 bg-black/40 rounded-2xl border border-white/5 space-y-2">
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Connections</span>
                      <span className="text-white">{edges.filter(e => e.source === selectedNodeData.id || e.target === selectedNodeData.id).length}</span>
                   </div>
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Blast Radius</span>
                      <span className={blastSet.size > 1 ? "text-red-500" : "text-emerald-500"}>{blastSet.size} Nodes</span>
                   </div>
                </div>

                {selectedNodeVulns.length > 0 ? (
                   <div className="space-y-2">
                      <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                         <ShieldAlert size={12} /> Active Vulnerabilities
                      </h4>
                      {selectedNodeVulns.map(v => (
                         <div key={v.id} className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl">
                            <p className="text-[10px] font-bold text-red-400 leading-tight">{v.title}</p>
                         </div>
                      ))}
                   </div>
                ) : (
                   <div className="flex items-center gap-2 text-emerald-500 bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/20">
                      <ShieldAlert size={16} />
                      <span className="text-[10px] font-black uppercase">Secure Resource</span>
                   </div>
                )}

                <button className="w-full py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-black text-white uppercase tracking-widest transition-all">
                   View HCL Definition
                </button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ScanResults } from '../components/ScanResults';
import { RemediationHUD } from '../components/RemediationHUD';
import { API } from '../services/backend';
import { Vulnerability, Severity, ScanStatus } from '../types';
import { 
  Play, Loader2, AlertCircle, ShieldCheck, RotateCcw, 
  History, Database, Sparkles, Lock, Code2, Terminal,
  LayoutTemplate, Check, ChevronRight, X, ArrowRight
} from 'lucide-react';

interface ScannerProps {
  code: string;
  onCodeChange: (code: string) => void;
  onScanComplete: (vulns: Vulnerability[]) => void;
  vulnerabilities: Vulnerability[];
  onApplyFix: (id: string, code: string) => void;
  onSimulateBlast: (vulnerability: Vulnerability) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ code, onCodeChange, onScanComplete, vulnerabilities, onApplyFix, onSimulateBlast }) => {
  const [scanning, setScanning] = useState(false);
  const [history, setHistory] = useState<any[]>([]);
  const [showBlueprints, setShowBlueprints] = useState(false);
  const [subscription, setSubscription] = useState<any>(null);

  // Remediation State
  const [remediationStatus, setRemediationStatus] = useState<'idle' | 'initializing' | 'patching' | 'pushing' | 'completed'>('idle');
  const [prData, setPrData] = useState<{ prUrl: string; branch: string } | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    const [hist, sub] = await Promise.all([
      API.getScanHistory(),
      API.getSubscriptionStatus()
    ]);
    setHistory(hist);
    setSubscription(sub);
  };

  const performScan = async () => {
    setScanning(true);
    try {
      const result = await API.scanInfrastructure(code);
      onScanComplete(result.vulns);
      await loadData();
    } catch (e) {
      console.error("Scan Error", e);
    } finally {
      setScanning(false);
    }
  };

  const handleApplyFixWithPR = async (vulnId: string, fixCode: string) => {
    setRemediationStatus('initializing');

    setTimeout(() => setRemediationStatus('patching'), 1000);
    setTimeout(() => setRemediationStatus('pushing'), 2500);

    const result = await API.createRemediationPR(vulnId, fixCode);

    setTimeout(() => {
      setPrData(result);
      setRemediationStatus('completed');
      onApplyFix(vulnId, fixCode); // Aplica localmente também
    }, 4000);
  };

  const applyBlueprint = (newCode: string) => {
    onCodeChange(newCode);
    setShowBlueprints(false);
  };

  const blueprints = [
    { 
      name: "S3: Ultra Secure Bucket", 
      desc: "Private, Encryption enabled, Public Access Blocked.", 
      code: `resource "aws_s3_bucket" "prod_assets" {
  bucket = "cloudguardian-customer-data"
}

resource "aws_s3_bucket_public_access_block" "block" {
  bucket = aws_s3_bucket.prod_assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}`
    },
    {
      name: "RDS: Private Database",
      desc: "Non-public, Var-based passwords.",
      code: `resource "aws_db_instance" "mysql_db" {
  allocated_storage    = 20
  engine               = "mysql"
  instance_class       = "db.t2.micro"
  db_name              = "production_db"
  username             = "admin"
  password             = var.db_password # Safe var injection
  publicly_accessible  = false           # Strictly private
  skip_final_snapshot  = false
}`
    },
    {
      name: "VPC: SOC2 Compliant Network",
      desc: "3 AZs, Private Subnets, NAT Gateway.",
      code: `module "vpc" {
  source = "terraform-aws-modules/vpc/aws"
  name   = "soc2-vpc"
  cidr   = "10.0.0.0/16"

  azs             = ["us-east-1a", "us-east-1b"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24"]
  public_subnets  = ["10.0.101.0/24", "10.0.102.0/24"]

  enable_nat_gateway = true
  enable_vpn_gateway = true
}`
    }
  ];

  const renderCode = (text: string) => {
    return text.split('\n').map((line, i) => (
      <div key={i} className="flex min-h-[1.5rem] group hover:bg-white/[0.03]">
        <span className="w-10 text-right pr-4 text-slate-700 font-mono text-xs pt-0.5 border-r border-white/5 mr-4 select-none">{i + 1}</span>
        <span className="flex-1 whitespace-pre font-mono text-xs leading-6 text-slate-400">{line || ' '}</span>
      </div>
    ));
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in duration-700 relative">

      {remediationStatus !== 'idle' && (
        <RemediationHUD 
          status={remediationStatus as any} 
          prUrl={prData?.prUrl} 
          branch={prData?.branch} 
          onClose={() => { setRemediationStatus('idle'); setPrData(null); }} 
        />
      )}

      {/* Blueprints Sidebar Overlay */}
      {showBlueprints && (
        <div className="fixed inset-0 z-[120] flex justify-end animate-in fade-in duration-300">
           <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowBlueprints(false)}></div>
           <div className="relative w-full max-w-md bg-slate-950 border-l border-white/10 h-full shadow-2xl p-10 flex flex-col space-y-10 animate-in slide-in-from-right duration-500 overflow-y-auto custom-scrollbar">
              <div className="flex justify-between items-center">
                 <h3 className="text-3xl font-black text-white uppercase italic tracking-tighter">Safe <span className="text-primary-500">Blueprints</span></h3>
                 <button onClick={() => setShowBlueprints(false)} className="p-2 hover:bg-white/5 rounded-xl"><X size={24}/></button>
              </div>
              <p className="text-slate-500 text-xs font-medium leading-relaxed">
                 Substitua snippets inseguros por padrões testados e certificados pela nossa equipe de SecOps.
              </p>

              <div className="space-y-6">
                 {blueprints.map((b, i) => (
                   <div key={i} className="neo-card rounded-[32px] p-6 space-y-6 border border-white/5 hover:border-primary-500/30 transition-all cursor-pointer group" onClick={() => applyBlueprint(b.code)}>
                      <div className="flex justify-between items-start">
                         <div className="p-3 bg-primary-500/10 rounded-2xl text-primary-500">
                            <LayoutTemplate size={24} />
                         </div>
                         <div className="text-[8px] font-black text-slate-600 uppercase tracking-widest border border-white/5 px-2 py-1 rounded">HCL Pattern</div>
                      </div>
                      <div>
                         <h4 className="text-lg font-black text-white mb-1 group-hover:text-primary-400 transition-colors">{b.name}</h4>
                         <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tight leading-relaxed">{b.desc}</p>
                      </div>
                      <div className="pt-4 border-t border-white/5 flex items-center justify-between text-[9px] font-black text-primary-500 uppercase tracking-widest">
                         <span>Apply to Forge</span>
                         <ArrowRight size={14} className="group-hover:translate-x-1 transition-transform" />
                      </div>
                   </div>
                 ))}
              </div>
           </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <Code2 size={12} className="text-primary-500" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Code Security Forge</span>
          </div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
            Vulnerability <span className="text-primary-500">Scanner</span>
          </h2>
        </div>

        <div className="flex gap-4">
           <button 
            onClick={() => setShowBlueprints(true)}
            className="flex items-center gap-3 px-6 py-4 bg-white/5 hover:bg-white/10 border border-white/10 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all active:scale-95"
           >
             <LayoutTemplate size={16} /> Safe Blueprints
           </button>
           <button 
            onClick={performScan} 
            disabled={scanning} 
            className="flex items-center gap-3 px-10 py-4 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/40 disabled:opacity-50 active:scale-95 group"
           >
            {scanning ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" className="group-hover:translate-x-0.5 transition-transform" />}
            {scanning ? 'Analyzing Infrastructure...' : 'Initiate Security Scan'}
           </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8 neo-card rounded-[40px] overflow-hidden flex flex-col min-h-[650px] shadow-2xl relative">
          <div className="bg-slate-900/60 backdrop-blur-md px-8 py-4 border-b border-white/5 flex justify-between items-center">
            <div className="flex items-center gap-4">
               <div className="flex gap-1.5">
                  <div className="w-2.5 h-2.5 rounded-full bg-red-500/30"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-amber-500/30"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/30"></div>
               </div>
               <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-l border-white/5 pl-4">main.tf • Terraform HCL</span>
            </div>
            <div className="text-[9px] font-black text-primary-500 bg-primary-500/10 px-3 py-1 rounded-full uppercase tracking-widest">IA Real-time Monitoring</div>
          </div>

          <div className="flex-1 relative bg-slate-950/40 p-8 overflow-y-auto custom-scrollbar">
            <textarea 
              value={code} 
              onChange={(e) => onCodeChange(e.target.value)} 
              className="absolute inset-0 w-full h-full p-8 pl-16 bg-transparent text-transparent caret-white font-mono text-xs leading-6 resize-none focus:outline-none z-10"
              spellCheck={false}
              placeholder="Cole seu código Terraform HCL aqui..."
            />
            <div className="pointer-events-none relative z-0">{renderCode(code)}</div>
          </div>

          <div className="p-4 bg-slate-900/40 border-t border-white/5 flex justify-between items-center text-[9px] font-black text-slate-600 uppercase tracking-widest">
             <div className="flex gap-6">
                <span className="flex items-center gap-2"><Terminal size={12}/> UTF-8</span>
                <span className="flex items-center gap-2"><History size={12}/> Git: main</span>
             </div>
             <span>Lines: {code.split('\n').length}</span>
          </div>
