            isAuditor ? 'bg-amber-500/10 border-amber-500/30 text-amber-500' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-white'
          }`}
        >
          {isAuditor ? <Shield size={12} /> : <User size={12} />}
