import React, { useState, useEffect } from 'react';
import { 
  Hammer, Plus, ShieldCheck, Zap, Terminal, Code, 
  Trash2, Play, Loader2, Save, Search, Filter,
  Layers, Globe, CheckCircle2, AlertTriangle, ChevronRight, X, Sparkles
} from 'lucide-react';
import { Severity, Guardrail } from '../types';
import { API } from '../services/backend';
import { GoogleGenAI } from "@google/genai";

export const PolicyForge: React.FC<{ onNotify: (m: string) => void }> = ({ onNotify }) => {
  const [guardrails, setGuardrails] = useState<Guardrail[]>([]);
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [testCode, setTestCode] = useState('resource "aws_s3_bucket" "test" {\n  acl = "public-read"\n}');
  const [testResult, setTestResult] = useState<any>(null);
  const [testing, setTesting] = useState(false);

  // AI Generation State
  const [aiPrompt, setAiPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);

  // Form state
  const [newGR, setNewGR] = useState({
    name: '',
    description: '',
    resourceType: 'aws_s3_bucket',
    logic: '',
    severity: Severity.HIGH
  });

  useEffect(() => {
    loadGuardrails();
  }, []);

  const loadGuardrails = async () => {
    setLoading(true);
    const data = await API.getGuardrails();
    setGuardrails(data);
    setLoading(false);
  };

  const handleCreateGuardrail = async (e: React.FormEvent) => {
    e.preventDefault();
    const gr: Guardrail = {
      id: `gr-${Date.now()}`,
      ...newGR,
      status: 'enabled'
    };
    await API.saveGuardrail(gr);
    setGuardrails([gr, ...guardrails]);
    setIsModalOpen(false);
    onNotify("Novo Guardrail ativado e injetado no motor de Scan.");
    setNewGR({ name: '', description: '', resourceType: 'aws_s3_bucket', logic: '', severity: Severity.HIGH });
    setAiPrompt('');
  };

  const generateLogic = async () => {
    if (!aiPrompt) return;
    setIsGenerating(true);
    try {
      // Direct call to Gemini for policy generation
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Translate this security requirement into a simple pseudo-code or Rego logic for Terraform: "${aiPrompt}". 
        Example output: "encryption == true" or "ingress.cidr != 0.0.0.0/0". 
        Keep it one line if possible.`,
      });

      const logic = response.text?.trim() || '/* Could not generate logic */';
      setNewGR(prev => ({ ...prev, logic, description: aiPrompt, name: prev.name || "Auto-Generated Policy" }));
    } catch (e) {
      console.error(e);
      onNotify("Erro ao gerar política com IA.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleTestPolicy = async () => {
    setTesting(true);
    await new Promise(r => setTimeout(r, 1200));
    // Simulação rigorosa: Verifica se alguma política ativa é violada pelo código de teste
    const violation = guardrails.some(g => g.status === 'enabled' && testCode.includes(g.resourceType) && !testCode.includes(g.logic.split('==')[1]?.trim() || 'safe'));

    setTestResult({
      status: violation ? 'FAIL' : 'PASS',
      message: violation ? 'Policy Violation: Code snippet violates active guardrails.' : 'Compliance Validated: No violations found.',
      impact: violation ? 'HIGH' : 'NONE'
    });
    setTesting(false);
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-12 animate-in fade-in duration-700 pb-32">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <Hammer size={12} className="text-primary-500" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Guardrail Engineering Studio</span>
          </div>
          <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
            Policy <span className="text-primary-500">Forge</span>
          </h2>
        </div>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-3 px-8 py-3 bg-primary-600 hover:bg-primary-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/40 active:scale-95 group"
        >
          <Plus size={16} className="group-hover:rotate-90 transition-transform" />
          Create New Guardrail
        </button>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-7 space-y-6">
           <div className="flex justify-between items-center text-[11px] font-black text-white uppercase tracking-widest px-2">
              <span className="flex items-center gap-2"><Layers size={14} className="text-primary-500" /> Active Guardrails</span>
              <span className="text-slate-500">{guardrails.length} Registered</span>
           </div>

           {loading ? (
             <div className="h-64 flex flex-col items-center justify-center gap-4 bg-slate-900/20 rounded-[40px] border border-white/5">
                <Loader2 className="animate-spin text-primary-500" size={32} />
                <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">Fetching Rego Store...</span>
             </div>
           ) : (
             <div className="space-y-4">
               {guardrails.map((gr) => (
                 <div key={gr.id} className="neo-card rounded-[32px] p-6 border border-white/5 hover:border-primary-500/20 transition-all group">
                    <div className="flex justify-between items-start mb-6">
                       <div className="flex items-center gap-4">
                          <div className={`p-3 rounded-2xl ${gr.severity === Severity.CRITICAL ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                             <ShieldCheck size={24} />
                          </div>
                          <div>
                             <h4 className="text-lg font-black text-white uppercase italic tracking-tight">{gr.name}</h4>
                             <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{gr.resourceType}</p>
                          </div>
                       </div>
                       <div className="flex items-center gap-3">
                          <span className={`text-[8px] font-black px-2 py-0.5 rounded-full border ${gr.status === 'enabled' ? 'bg-emerald-500/5 text-emerald-500 border-emerald-500/10' : 'bg-slate-800 text-slate-500'}`}>
                            {gr.status.toUpperCase()}
                          </span>
                       </div>
                    </div>

                    <div className="bg-slate-950/60 rounded-2xl p-4 border border-white/5 group-hover:border-primary-500/10 transition-colors">
                       <div className="flex items-center gap-2 text-[8px] font-black text-slate-600 uppercase tracking-widest mb-2">
                          <Terminal size={10} /> Enforcement Logic
                       </div>
                       <code className="text-xs text-primary-400 font-mono italic">{gr.logic}</code>
                    </div>
                 </div>
               ))}
             </div>
           )}
        </div>

        <div className="lg:col-span-5 space-y-8">
           <section className="bg-slate-900 border border-white/5 rounded-[40px] p-10 space-y-8 shadow-2xl relative overflow-hidden flex flex-col h-full">
              <div className="absolute top-0 right-0 p-8 opacity-5">
                 <Zap size={100} />
              </div>
              <h3 className="text-2xl font-black text-white uppercase italic tracking-tighter">Policy <span className="text-primary-500">Sandbox</span></h3>
              <div className="flex-1 bg-slate-950 rounded-3xl border border-white/5 p-6 flex flex-col space-y-4 shadow-inner">
                 <textarea 
                    value={testCode}
                    onChange={(e) => setTestCode(e.target.value)}
                    className="flex-1 bg-transparent text-primary-300 font-mono text-xs resize-none focus:outline-none custom-scrollbar leading-relaxed"
                 />
                 <button 
                    onClick={handleTestPolicy}
                    disabled={testing}
                    className="w-full py-4 bg-white/5 hover:bg-white/10 border border-white/10 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all flex items-center justify-center gap-2"
                 >
                    {testing ? <Loader2 className="animate-spin" size={14} /> : <Play size={14} />}
                    Test Local Snippet
                 </button>
              </div>

              {testResult && (
                <div className={`p-6 rounded-3xl border animate-in zoom-in-95 ${testResult.status === 'FAIL' ? 'bg-red-500/5 border-red-500/20' : 'bg-emerald-500/5 border-emerald-500/20'}`}>
                   <p className="text-xs text-slate-300 font-medium leading-relaxed italic">"{testResult.message}"</p>
                </div>
              )}
           </section>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[130] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in">
           <div className="bg-slate-900 border border-white/5 w-full max-w-xl rounded-[48px] shadow-2xl p-10 relative">
              <button onClick={() => setIsModalOpen(false)} className="absolute top-8 right-8 text-slate-500 hover:text-white"><X size={24}/></button>
              <h3 className="text-3xl font-black text-white uppercase italic tracking-tighter mb-8">New <span className="text-primary-500">Guardrail</span></h3>

              {/* AI Generator Section */}
              <div className="mb-8 p-1 bg-gradient-to-r from-primary-600 to-indigo-600 rounded-3xl">
                 <div className="bg-slate-950 rounded-[22px] p-6 space-y-4">
                    <div className="flex items-center gap-2 text-primary-400">
                       <Sparkles size={16} />
                       <span className="text-[10px] font-black uppercase tracking-widest">AI Generator</span>
                    </div>
                    <div className="flex gap-2">
                       <input 
                          value={aiPrompt}
                          onChange={(e) => setAiPrompt(e.target.value)}
                          placeholder="Ex: Block public S3 buckets in production"
                          className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs text-white focus:outline-none focus:border-primary-500"
                          onKeyDown={(e) => e.key === 'Enter' && generateLogic()}
                       />
                       <button 
                          onClick={generateLogic}
                          disabled={isGenerating}
                          className="px-4 bg-white/10 hover:bg-white/20 rounded-xl text-white transition-all disabled:opacity-50"
                       >
                          {isGenerating ? <Loader2 size={16} className="animate-spin"/> : <ChevronRight size={16} />}
                       </button>
                    </div>
                 </div>
              </div>

              <form onSubmit={handleCreateGuardrail} className="space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Rule Name</label>
                    <input 
                       required
                       value={newGR.name}
                       onChange={e => setNewGR({...newGR, name: e.target.value})}
                       className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-white text-sm focus:border-primary-500 focus:outline-none"
                       placeholder="Ex: Mandatory KMS Encryption"
                    />
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Resource Type</label>
                        <select 
                          className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-white text-sm"
                          value={newGR.resourceType}
                          onChange={e => setNewGR({...newGR, resourceType: e.target.value})}
                        >
                           <option value="aws_s3_bucket">aws_s3_bucket</option>
                           <option value="aws_db_instance">aws_db_instance</option>
                           <option value="aws_security_group">aws_security_group</option>
                           <option value="aws_instance">aws_instance</option>
                        </select>
                    </div>
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Severity</label>
                        <select 
                          className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-white text-sm"
                          value={newGR.severity}
                          onChange={e => setNewGR({...newGR, severity: e.target.value as Severity})}
                        >
                           <option value={Severity.LOW}>LOW</option>
                           <option value={Severity.MEDIUM}>MEDIUM</option>
                           <option value={Severity.HIGH}>HIGH</option>
                           <option value={Severity.CRITICAL}>CRITICAL</option>
                        </select>
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Enforcement Logic (Rego/HCL)</label>
                    <input 
                       required
                       value={newGR.logic}
                       onChange={e => setNewGR({...newGR, logic: e.target.value})}
                       className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-primary-400 font-mono text-xs focus:border-primary-500 focus:outline-none"
                       placeholder="Ex: encryption_enabled == true"
                    />
                 </div>
                 <button type="submit" className="w-full py-5 bg-primary-600 hover:bg-primary-700 text-white font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl">
                    Deploy to CloudGuardian Engine
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Terminal, Github, GitBranch, ShieldCheck, CheckCircle2, XCircle, Clock, Play, ArrowUpRight, GitCommit, Loader2, ChevronRight, Copy, Check, FileCode, Zap, AlertTriangle, ShieldAlert, GitMerge, Lock, Shield, Layers } from 'lucide-react';
import { PipelineRun, Severity } from '../types';

interface PipelineInsightsProps {
  runs: PipelineRun[];
  setRuns: React.Dispatch<React.SetStateAction<PipelineRun[]>>;
  onNotify: (msg: string) => void;
  onTimeline: (event: any) => void;
}

export const PipelineInsights: React.FC<PipelineInsightsProps> = ({ runs, setRuns, onNotify, onTimeline }) => {
  const [isTriggering, setIsTriggering] = useState(false);
  const [currentStage, setCurrentStage] = useState(0); // 0: Idle, 1: Checkout, 2: Scan, 3: Validation, 4: Complete
  const [activeTab, setActiveTab] = useState<'history' | 'workflow' | 'pr-simulator'>('history');
  const [logs, setLogs] = useState<string[]>([]);
  const [copied, setCopied] = useState(false);

  // PR Simulator State
  const [prState, setPrState] = useState<'idle' | 'detected' | 'fixing' | 'resolved' | 'ignored'>('detected');

  // Config State
  const [config, setConfig] = useState({
    failOnCritical: true,
    autoFix: true,
    enforceTags: false,
    deepSecretScan: true,
    prComments: true
  });

  const logEndRef = useRef<HTMLDivElement>(null);

  const workflowYaml = `name: CloudGuardian Security Scan

on:
  pull_request:
    branches: [ main, develop ]
    paths:
      - '**.tf'
      - '**.tfvars'

jobs:
  security_scan:
    name: CloudGuardian IaC Analysis
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Code
        uses: actions/checkout@v3

      - name: Run CloudGuardian Engine
        uses: cloudguardian/scanner-action@v1
        with:
          api_key: \${{ secrets.CG_API_KEY }}
          fail_on_critical: true
          output_format: github-pr-comment

      - name: AI Auto-Remediation Suggestion
        if: failure()
        run: echo "CloudGuardian detectou vulnerabilidades. Verifique os comentários no PR."`;

  const addLog = (msg: string) => setLogs(prev => [...prev, `[${new Date().toLocaleTimeString()}] ${msg}`]);

  useEffect(() => {
    if (logEndRef.current) logEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const copyToClipboard = () => {
    navigator.clipboard.writeText(workflowYaml);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    onNotify("Workflow copiado para o clipboard!");
  };

  const triggerManualScan = () => {
    setIsTriggering(true);
    setCurrentStage(1);
    setLogs([]);

    // Stage 1: Checkout
    addLog("Initializing CloudGuardian CI/CD Runner v2.4...");
    addLog("Fetching Terraform HCL context...");

    setTimeout(() => {
      setCurrentStage(2);
      addLog("Running SAST analysis with Gemini Engine...");

      setTimeout(() => {
        setCurrentStage(3);
        addLog("Policy validation: SOC2 CC6.6 - PASS");
        addLog("Policy validation: ISO27001 A.10 - PASS");

        setTimeout(() => {
          setCurrentStage(4);
          addLog("Finalizing results and reporting to central dashboard...");

          setTimeout(() => {
            const newRun: PipelineRun = {
              id: `run-${Math.floor(Math.random() * 1000)}`,
              branch: 'main',
              status: 'success',
              vulns: 0,
              timestamp: new Date().toISOString(),
              commit: 'manual: security baseline scan'
            };

            setRuns(prev => [newRun, ...prev]);
            setIsTriggering(false);
            setCurrentStage(0);
            onNotify("Pipeline executado com sucesso!");
            onTimeline({
              type: 'PIPELINE',
              title: 'Pipeline Ad-Hoc Concluído',
              description: 'Scan manual de infraestrutura validado. Status: Clean.',
              severity: Severity.LOW
            });
          }, 800);
        }, 1200);
      }, 1500);
    }, 1500);
  };

  const initPRSimulation = () => {
    setActiveTab('pr-simulator');
    setPrState('detected');
    onNotify("Simulação de PR Guard iniciada. Violação detectada.");

    // Add failed run to history
    const failedRun: PipelineRun = {
        id: `run-${Math.floor(Math.random() * 1000)}`,
        branch: 'feat/new-s3-bucket',
        status: 'failed',
        vulns: 1,
        timestamp: new Date().toISOString(),
        commit: 'feat: add public bucket',
        prNumber: Math.floor(Math.random() * 100) + 50
    };
    setRuns(prev => [failedRun, ...prev]);
  };

  const handleApplyAutoPR = () => {
    setPrState('fixing');
    setTimeout(() => {
        setPrState('resolved');
        onNotify("Correção aplicada e PR mergeado com sucesso!");

        const successRun: PipelineRun = {
            id: `run-${Math.floor(Math.random() * 1000)}`,
            branch: 'feat/new-s3-bucket',
            status: 'success',
            vulns: 0,
            timestamp: new Date().toISOString(),
            commit: 'fix(security): restrict s3 access',
            prNumber: Math.floor(Math.random() * 100) + 50
        };
        setRuns(prev => [successRun, ...prev]);

        onTimeline({
            type: 'PR',
            title: 'Auto-Remediação CI/CD',
            description: 'CloudGuardian Bot corrigiu e mergeou o PR #82 automaticamente.',
            severity: Severity.LOW
        });
    }, 2500);
  };

  const handleIgnorePR = () => {
      setPrState('ignored');
      onNotify("Risco aceito. PR liberado manualmente.");
      onTimeline({
        type: 'PR',
        title: 'Risco Aceito (Bypass)',
        description: 'Usuário forçou o merge do PR #82 ignorando alertas de segurança.',
        severity: Severity.MEDIUM
    });
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-8 animate-in fade-in duration-500 text-slate-200">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div className="space-y-1">
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic">Pipeline Insights</h2>
          <p className="text-slate-400 text-sm">Integração nativa de segurança no fluxo de CI/CD (Shift-Left).</p>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={triggerManualScan}
            disabled={isTriggering}
            className="flex items-center gap-2 px-6 py-3 bg-slate-800 hover:bg-slate-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl border border-slate-700 transition-all shadow-xl disabled:opacity-50 active:scale-95"
          >
            {isTriggering ? <Loader2 className="animate-spin" size={16} /> : <Play size={16} fill="currentColor" />}
            {isTriggering ? 'Executing...' : 'Manual Scan'}
          </button>
          <button 
            onClick={initPRSimulation}
            className="flex items-center gap-2 px-6 py-3 bg-primary-600 hover:bg-primary-700 text-white text-[10px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30 active:scale-95"
          >
            <Zap size={16} />
            Simular PR Guard
          </button>
        </div>
      </header>

      {/* Tabs */}
      <div className="flex gap-2 p-1 bg-slate-900 rounded-2xl w-fit border border-slate-800">
        <TabButton active={activeTab === 'history'} onClick={() => setActiveTab('history')} label="Run History" icon={<Clock size={14}/>} />
        <TabButton active={activeTab === 'workflow'} onClick={() => setActiveTab('workflow')} label="Setup Workflow" icon={<FileCode size={14}/>} />
        <TabButton active={activeTab === 'pr-simulator'} onClick={() => setActiveTab('pr-simulator')} label="PR Guard Simulator" icon={<Github size={14}/>} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8 space-y-6">
          {activeTab === 'history' && (
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 space-y-8 shadow-2xl relative overflow-hidden flex flex-col min-h-[500px]">
               <div className="absolute top-0 right-0 p-8 opacity-5">
                  <Github size={120} />
               </div>

               {isTriggering ? (
                 <div className="space-y-6 relative z-10">
                    <div className="flex justify-between items-center px-4">
                       <StageNode label="Checkout" status={currentStage >= 1 ? (currentStage > 1 ? 'done' : 'active') : 'pending'} />
                       <div className={`h-0.5 flex-1 mx-2 transition-all duration-500 ${currentStage > 1 ? 'bg-primary-500' : 'bg-slate-800'}`}></div>
                       <StageNode label="Scan Analysis" status={currentStage >= 2 ? (currentStage > 2 ? 'done' : 'active') : 'pending'} />
                       <div className={`h-0.5 flex-1 mx-2 transition-all duration-500 ${currentStage > 2 ? 'bg-primary-500' : 'bg-slate-800'}`}></div>
                       <StageNode label="Policy Check" status={currentStage >= 3 ? (currentStage > 3 ? 'done' : 'active') : 'pending'} />
                       <div className={`h-0.5 flex-1 mx-2 transition-all duration-500 ${currentStage > 3 ? 'bg-primary-500' : 'bg-slate-800'}`}></div>
                       <StageNode label="Report" status={currentStage >= 4 ? 'done' : 'pending'} />
                    </div>

                    <div className="bg-black/80 rounded-2xl p-6 border border-slate-800 font-mono text-[10px] text-emerald-500 min-h-[200px] max-h-[200px] overflow-y-auto space-y-1 custom-scrollbar animate-in zoom-in-95 shadow-inner">
                        {logs.map((log, i) => (
                          <div key={i} className="flex gap-3">
                            <ChevronRight size={10} className="mt-0.5 opacity-50" />
                            <span>{log}</span>
                          </div>
                        ))}
                        <div ref={logEndRef} />
                    </div>
                 </div>
               ) : (
                 <div className="space-y-4 relative z-10 flex-1">
