  );
};

const QuotaBar = ({ label, used, limit, unit, provider, icon }: any) => {
  const percentage = Math.min((used / limit) * 100, 100);
  const color = percentage > 85 ? 'bg-red-500' : percentage > 60 ? 'bg-amber-500' : 'bg-primary-500';

  return (
    <div className="space-y-3">
       <div className="flex justify-between items-start">
          <div className="flex items-center gap-2">
             <div className="text-slate-500">{icon}</div>
             <div>
                <div className="text-[10px] font-black text-white uppercase tracking-tight">{label}</div>
                <div className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">{provider}</div>
             </div>
          </div>
          <div className="text-right">
             <div className="text-xs font-black text-white">{used.toLocaleString()} <span className="text-[8px] text-slate-500">{unit}</span></div>
             <div className="text-[8px] font-bold text-slate-600">of {limit.toLocaleString()}</div>
          </div>
       </div>
       <div className="h-2 w-full bg-slate-950 rounded-full overflow-hidden border border-white/5">
          <div className={`h-full ${color} transition-all duration-1000`} style={{ width: `${percentage}%` }}></div>
       </div>
    </div>
  );
};

const ConnectorCard = ({ provider, status, loading, onTest, icon }: any) => (
  <div className="neo-card p-6 rounded-[32px] space-y-4 border border-white/5">
    <div className="flex justify-between items-center">
      <div className="flex items-center gap-3">
        <div className="p-2 bg-slate-900 rounded-xl border border-white/5 text-primary-400">
          {icon}
        </div>
        <span className="text-[10px] font-black text-white uppercase tracking-tight">{provider}</span>
      </div>
      <div className={`w-2 h-2 rounded-full ${status === 'online' ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-slate-700'}`}></div>
    </div>
    <button 
      onClick={onTest}
      disabled={loading}
      className="w-full py-2 bg-white/5 border border-white/10 rounded-xl text-[9px] font-black text-slate-500 uppercase tracking-widest hover:border-primary-500/30 hover:text-white transition-all flex items-center justify-center gap-2"
    >
      {loading ? <Loader2 className="animate-spin" size={12} /> : <Share2 size={12} />}
      {loading ? 'Testing...' : 'Test Link'}
    </button>
  </div>
);

const InputGroup = ({ label, value, type, options, onChange, placeholder }: any) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">{label}</label>
    {type === 'select' ? (
      <select 
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-xs text-white focus:outline-none focus:border-primary-500 shadow-inner"
      >
        {options.map((o: string) => <option key={o} value={o}>{o}</option>)}
      </select>
    ) : (
      <input 
        type={type} 
        value={value} 
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full bg-slate-950 border border-white/10 rounded-2xl px-6 py-4 text-xs text-white focus:outline-none focus:border-primary-500 shadow-inner placeholder:text-slate-700" 
      />
    )}
  </div>
);

const ConfigToggle = ({ label, active, onToggle }: any) => (
  <div className="flex items-center justify-between group cursor-pointer" onClick={onToggle}>
    <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest group-hover:text-slate-300 transition-colors">{label}</span>
    <div className={`w-10 h-5 rounded-full relative transition-all border ${active ? 'bg-primary-600 border-primary-500' : 'bg-slate-900 border-white/10'}`}>
      <div className={`absolute top-0.5 w-3 h-3 rounded-full transition-all bg-white ${active ? 'right-0.5' : 'left-0.5'}`}></div>
    </div>
  </div>
);

import React, { useMemo, useEffect, useState } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, AreaChart, Area, XAxis, YAxis, Tooltip } from 'recharts';
import { 
  DollarSign, RefreshCw, GitPullRequest, ArrowRight, ShieldCheck, 
  Globe, Target, Zap, AlertTriangle, TrendingUp, CheckCircle2, Radar, Newspaper, TrendingDown, Activity, Flame
} from 'lucide-react';
import { SecurityScore, Vulnerability, DriftItem, TimelineEvent, Severity, Policy, PipelineRun } from '../types';
import { API } from '../services/backend';
import { getComplianceReport } from '../services/engine';

interface DashboardProps {
  vulnerabilities: Vulnerability[];
  drifts: DriftItem[];
  score: SecurityScore;
  timeline: TimelineEvent[];
  onNavigate: (view: any) => void;
  policies: Policy[];
  runs: PipelineRun[];
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  vulnerabilities, drifts, score, onNavigate
}) => {
  const [threats, setThreats] = useState<any[]>([]);
  const [loadingThreats, setLoadingThreats] = useState(false);
  const [liveData, setLiveData] = useState<{time: string, value: number}[]>([]);

  useEffect(() => {
    loadThreats();

    // Init live data
    const initialData = Array.from({ length: 20 }, (_, i) => ({
      time: i.toString(),
      value: 20 + Math.random() * 10
    }));
    setLiveData(initialData);

    const interval = setInterval(() => {
      setLiveData(prev => {
        const newData = [...prev.slice(1), {
          time: new Date().toISOString(),
          value: 20 + Math.random() * 30 + (Math.random() > 0.9 ? 40 : 0) // Occasional spikes
        }];
        return newData;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const loadThreats = async () => {
    setLoadingThreats(true);
    const data = await API.getThreatBriefing();
    setThreats(data);
    setLoadingThreats(false);
  };

  const complianceData = getComplianceReport(vulnerabilities);
  const compliancePercent = complianceData.length > 0 ? Math.round((complianceData.filter(c => c.status === 'PASS').length / complianceData.length) * 100) : 100;

  const scoreChartData = useMemo(() => [
    { name: 'Score', value: score.total },
    { name: 'Gap', value: Math.max(0, 100 - score.total) },
  ], [score.total]);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in duration-700 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_#10b981]"></span>
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Fleet Monitor v3.4-Stable</span>
          </div>
          <h2 className="text-5xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
            Command <span className="text-primary-500">Center</span>
          </h2>
        </div>

        <div className="flex items-center gap-4">
          <div className="neo-card px-6 py-3 rounded-2xl flex items-center gap-4 border border-emerald-500/20 bg-emerald-500/5 group hover:bg-emerald-500/10 transition-colors">
             <div className="text-right border-r border-white/10 pr-4 mr-1">
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">ROI (Savings)</div>
                <div className="text-xl font-black text-emerald-500 leading-none">+${(vulnerabilities.length * 1450).toLocaleString()}</div>
             </div>
             <div className="flex items-center gap-3">
                <div className="p-2 bg-slate-900 rounded-lg shadow-lg border border-white/5">
                    <Flame size={18} className="text-white" />
                </div>
                <div>
                    <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Burn Rate</div>
                    <div className="text-xl font-black text-white leading-none">$0.00</div>
                </div>
             </div>
          </div>
          <button onClick={loadThreats} className="p-3 bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 transition-all text-slate-400">
            <RefreshCw size={20} className={loadingThreats ? 'animate-spin' : ''} />
          </button>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8 neo-card rounded-[48px] p-10 relative overflow-hidden border border-white/5 shadow-2xl bg-slate-900/40">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-center">
            <div className="flex flex-col items-center justify-center relative min-h-[350px]">
              <div className="w-80 h-80 relative">
                <ResponsiveContainer width="100%" height="100%" aspect={1}>
                  <PieChart>
                    <Pie data={scoreChartData} cx="50%" cy="50%" innerRadius={105} outerRadius={135} dataKey="value" startAngle={225} endAngle={-45} stroke="none" cornerRadius={20}>
                      <Cell fill={score.total > 75 ? "url(#gradGreen)" : "url(#gradRed)"} />
                      <Cell fill="rgba(255,255,255,0.03)" />
                    </Pie>
                    <defs>
                      <linearGradient id="gradGreen" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#10b981" /><stop offset="100%" stopColor="#3b82f6" /></linearGradient>
                      <linearGradient id="gradRed" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="#ef4444" /><stop offset="100%" stopColor="#f59e0b" /></linearGradient>
                    </defs>
                  </PieChart>
                </ResponsiveContainer>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                  <div className="text-7xl font-black text-white tracking-tighter text-glow">{score.total}</div>
                  <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mt-2">Health Index</div>
                </div>
              </div>
            </div>

            <div className="space-y-8">
              <div className="flex justify-between items-center">
                <h3 className="text-3xl font-black text-white uppercase italic tracking-tighter leading-none">Live <br/><span className="text-primary-500">Heartbeat</span></h3>
                <div className="p-3 bg-white/5 rounded-2xl text-emerald-500 animate-pulse">
                   <Activity size={20} />
                </div>
              </div>

              <div className="h-32 w-full bg-slate-950/30 rounded-2xl border border-white/5 overflow-hidden relative">
                 <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={liveData}>
                       <defs>
                          <linearGradient id="liveHeartbeat" x1="0" y1="0" x2="0" y2="1">
                             <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.4}/>
                             <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                          </linearGradient>
                       </defs>
                       <Area 
                          type="monotone" 
                          dataKey="value" 
                          stroke="#3b82f6" 
                          strokeWidth={2} 
                          fill="url(#liveHeartbeat)" 
                          isAnimationActive={false}
                       />
                    </AreaChart>
                 </ResponsiveContainer>
                 <div className="absolute top-2 left-3 text-[8px] font-black text-slate-500 uppercase tracking-widest">
                    Infrastructure Load (Real-time)
                 </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between p-4 bg-white/[0.02] border border-white/5 rounded-2xl group hover:bg-white/[0.04] transition-all">
                  <div className="flex items-center gap-3">
                    <Radar className="text-red-500 animate-pulse" size={18} />
                    <span className="text-xs font-bold text-slate-300">Active Vulnerabilities</span>
                  </div>
                  <div className="text-[10px] font-black text-red-500">{vulnerabilities.length} items</div>
                </div>
              </div>
              <button onClick={() => onNavigate('scanner')} className="w-full flex items-center justify-center gap-3 py-4 bg-primary-600 hover:bg-primary-700 text-white text-[11px] font-black uppercase tracking-widest rounded-2xl transition-all shadow-xl shadow-primary-900/30">
                Open Security Forge <ArrowRight size={16} />
              </button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-4 space-y-8 flex flex-col">
          <div className="neo-card rounded-[48px] p-8 flex-1 border border-white/5 shadow-2xl relative overflow-hidden bg-gradient-to-br from-slate-900 to-primary-950/20">
             <div className="flex justify-between items-center mb-6">
                <h4 className="text-[10px] font-black text-white uppercase tracking-widest flex items-center gap-2">
                   <Newspaper size={14} className="text-primary-400" /> AI Threat Intel Feed
                </h4>
             </div>

             <div className="space-y-4">
                {threats.map((t, i) => (
                  <div key={i} className="p-4 bg-black/40 border border-white/5 rounded-2xl group hover:border-primary-500/30 transition-all animate-in slide-in-from-right-4" style={{ animationDelay: `${i * 100}ms` }}>
                     <div className="flex items-center gap-2 mb-2">
                        <span className={`w-1.5 h-1.5 rounded-full ${t.severity === 'HIGH' ? 'bg-red-500' : 'bg-amber-500'}`}></span>
                        <span className="text-[10px] font-black text-white uppercase italic">{t.title}</span>
                     </div>
                     <p className="text-[10px] text-slate-500 leading-relaxed font-medium">{t.description}</p>
                  </div>
                ))}
             </div>
          </div>

          <div className="neo-card rounded-[32px] p-6 border border-emerald-500/20 bg-emerald-500/5">
             <div className="flex justify-between items-center text-[11px] font-bold">
               <span className="text-slate-400 uppercase tracking-widest">Global Compliance</span>
               <span className="text-emerald-500 font-black">{compliancePercent}%</span>
             </div>
             <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden mt-3 border border-white/5">
                <div className="h-full bg-emerald-500 shadow-[0_0_10px_#10b981]" style={{ width: `${compliancePercent}%` }}></div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

