interface GraphProps {
  code: string;
  vulnerabilities: Vulnerability[];
  focusedResourceId?: string | null;
}

export const Graph: React.FC<GraphProps> = ({ code, vulnerabilities, focusedResourceId }) => {
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [nodes, setNodes] = useState<SimNode[]>([]);
  const [edges, setEdges] = useState<GraphEdge[]>([]);

  // Viewport State
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Interaction Refs (Critical for smooth 60fps loop)
  const isDraggingCanvas = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });
  const draggedNode = useRef<{ id: string; x: number; y: number } | null>(null);

  // Initialize Graph Data
  useEffect(() => {
    const { nodes: rawNodes, edges: rawEdges } = parseHclToGraph(code);

    // Enrich nodes with vulnerabilities and initial positions
    const simNodes: SimNode[] = rawNodes.map((n, i) => ({
      ...n,
      x: Math.random() * 800, 
      y: Math.random() * 600,
      vx: 0,
      vy: 0,
      status: vulnerabilities.some(v => v.resource.includes(n.id)) ? 'risk' : 'healthy'
    }));

    setNodes(simNodes);
    setEdges(rawEdges);

    // Center view initially
    setPan({ x: window.innerWidth / 4, y: window.innerHeight / 6 });
  }, [code, vulnerabilities]);

  // Physics Engine
  useEffect(() => {
    let animationFrameId: number;

    const tick = () => {
      setNodes(prevNodes => {
        const newNodes = prevNodes.map(n => ({ ...n })); // Shallow copy

        // Constants
        const REPULSION = 6000;
        const SPRING = 0.02;
        const SPRING_LENGTH = 200;
        const DAMPING = 0.90; // Higher damping for 'floaty' space feel
        const CENTER_GRAVITY = 0.002; // Very low gravity to keep them "loose"

        // 1. Repulsion (Nodes push apart)
        for (let i = 0; i < newNodes.length; i++) {
          for (let j = i + 1; j < newNodes.length; j++) {
            const n1 = newNodes[i];
            const n2 = newNodes[j];
            const dx = n1.x - n2.x;
            const dy = n1.y - n2.y;
            const distSq = dx * dx + dy * dy || 1;
            const force = REPULSION / distSq;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            n1.vx += fx;
            n1.vy += fy;
            n2.vx -= fx;
            n2.vy -= fy;
          }
        }

        // 2. Spring (Edges pull together)
        edges.forEach(edge => {
          const source = newNodes.find(n => n.id === edge.source);
          const target = newNodes.find(n => n.id === edge.target);
          if (source && target) {
            const dx = target.x - source.x;
            const dy = target.y - source.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const force = (dist - SPRING_LENGTH) * SPRING;
            const angle = Math.atan2(dy, dx);

            const fx = Math.cos(angle) * force;
            const fy = Math.sin(angle) * force;

            source.vx += fx;
            source.vy += fy;
            target.vx -= fx;
            target.vy -= fy;
          }
        });

        // 3. Update Positions & Apply Damping
        newNodes.forEach(n => {
          // If node is being dragged, lock it to mouse position ref
          if (draggedNode.current && n.id === draggedNode.current.id) {
             n.x = draggedNode.current.x;
             n.y = draggedNode.current.y;
             n.vx = 0;
             n.vy = 0;
          } else {
             // Weak center gravity just to prevent them from drifting to infinity
             n.vx += (400 - n.x) * CENTER_GRAVITY;
             n.vy += (300 - n.y) * CENTER_GRAVITY;

             n.vx *= DAMPING;
             n.vy *= DAMPING;
             n.x += n.vx;
             n.y += n.vy;
          }
        });

        return newNodes;
      });
      animationFrameId = requestAnimationFrame(tick);
    };

    animationFrameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animationFrameId);
  }, [edges]); 

  // --- FIX: Global Mouse Up Listener ---
  useEffect(() => {
    const handleWindowMouseUp = () => {
        // Reset drag state globally when mouse is released anywhere
        draggedNode.current = null;
        isDraggingCanvas.current = false;
    };
    window.addEventListener('mouseup', handleWindowMouseUp);
    return () => window.removeEventListener('mouseup', handleWindowMouseUp);
  }, []);

  // Canvas Interactions
  const handleWheel = (e: React.WheelEvent) => {
    const newZoom = Math.min(Math.max(zoom - e.deltaY * 0.001, 0.2), 3);
    setZoom(newZoom);
  };

  const getGraphCoordinates = (clientX: number, clientY: number) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    return {
      x: (clientX - rect.left - pan.x) / zoom,
      y: (clientY - rect.top - pan.y) / zoom
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    // Check if we clicked a node
    const nodeElement = (e.target as Element).closest('[data-node-id]');

    if (nodeElement) {
      e.stopPropagation();
      const nodeId = nodeElement.getAttribute('data-node-id');
      if (nodeId) {
        const node = nodes.find(n => n.id === nodeId);
        if (node) {
          const coords = getGraphCoordinates(e.clientX, e.clientY);
          draggedNode.current = { id: nodeId, x: node.x, y: node.y }; 
          setSelectedNodeId(nodeId);
        }
      }
    } else {
      // Pan Canvas
      isDraggingCanvas.current = true;
      dragStart.current = { x: e.clientX - pan.x, y: e.clientY - pan.y };
    }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (draggedNode.current) {
      // Update the REF only, not state. The tick loop will pick it up.
      const coords = getGraphCoordinates(e.clientX, e.clientY);
      draggedNode.current.x = coords.x;
      draggedNode.current.y = coords.y;
    } else if (isDraggingCanvas.current) {
      // Panning updates React state immediately as it affects transform style
      setPan({ x: e.clientX - dragStart.current.x, y: e.clientY - dragStart.current.y });
    }
  };

  // Blast Radius Calculation
  const getBlastRadius = (nodeId: string) => {
    const affected = new Set<string>();
    const stack = [nodeId];
    while (stack.length > 0) {
      const curr = stack.pop()!;
      if (!affected.has(curr)) {
        affected.add(curr);
        edges.filter(e => e.source === curr).forEach(e => stack.push(e.target));
      }
    }
    return affected;
  };

  const blastSet = selectedNodeId ? getBlastRadius(selectedNodeId) : new Set();
  const selectedNodeData = nodes.find(n => n.id === selectedNodeId);
  const selectedNodeVulns = vulnerabilities.filter(v => selectedNodeData && v.resource.includes(selectedNodeData.id));

  return (
    <div className="h-[calc(100vh-2rem)] flex flex-col p-6 overflow-hidden">

      {/* Main Canvas */}
      <div 
        ref={containerRef}
        className="flex-1 bg-[#020617] rounded-[48px] border border-white/5 relative overflow-hidden shadow-2xl cursor-grab active:cursor-grabbing"
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
      >
        {/* Header Overlay */}
        <div className="absolute top-8 left-8 z-30 pointer-events-none">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <Activity className="text-primary-500 animate-pulse" size={14} />
              <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Live Topology Engine</span>
            </div>
            <h2 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none text-glow">
              Infra <span className="text-primary-500">Universe</span>
            </h2>
          </div>
        </div>

        {/* Controls Overlay */}
        <div className="absolute top-8 right-8 z-30 flex gap-2">
          <button onClick={() => setZoom(z => Math.min(z + 0.2, 3))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomIn size={18}/></button>
          <button onClick={() => setZoom(z => Math.max(z - 0.2, 0.2))} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><ZoomOut size={18}/></button>
          <button onClick={() => { setZoom(1); setPan({x: window.innerWidth/4, y: window.innerHeight/6}); }} className="p-3 bg-slate-900/80 backdrop-blur border border-white/10 rounded-xl hover:bg-white/10 transition-colors text-white shadow-lg"><Maximize2 size={18}/></button>
        </div>

        {/* Animated Background Grid */}
        <div className="absolute inset-0 opacity-[0.07] pointer-events-none" 
             style={{ 
               backgroundImage: 'linear-gradient(#4f46e5 1px, transparent 1px), linear-gradient(90deg, #4f46e5 1px, transparent 1px)', 
               backgroundSize: '50px 50px',
               transform: `scale(${zoom}) translate(${pan.x % 50}px, ${pan.y % 50}px)`
             }}>
        </div>

        <svg className="w-full h-full pointer-events-none">
          <g transform={`translate(${pan.x}, ${pan.y}) scale(${zoom})`}>
            {/* Edges */}
            {edges.map(edge => {
              const src = nodes.find(n => n.id === edge.source);
              const tgt = nodes.find(n => n.id === edge.target);
              if (!src || !tgt) return null;

              const isBlastPath = blastSet.has(edge.source) && blastSet.has(edge.target);
              // Dim unrelated edges if a node is selected
              const opacity = selectedNodeId ? (isBlastPath ? 1 : 0.1) : 0.4;
              const strokeColor = isBlastPath ? '#ef4444' : '#1e293b';
              const strokeWidth = isBlastPath ? 3 : 1;

              return (
                <g key={edge.id} className="transition-all duration-300">
                  <line 
                    x1={src.x} y1={src.y} x2={tgt.x} y2={tgt.y} 
                    stroke={strokeColor} 
                    strokeWidth={strokeWidth}
                    opacity={opacity}
                  />
                  {/* Traffic Animation - Only active on blast path when selected */}
                  {(isBlastPath || !selectedNodeId) && (
                    <circle r={isBlastPath ? 3 : 2} fill={isBlastPath ? '#ef4444' : '#3b82f6'}>
                      <animateMotion 
                        dur={isBlastPath ? "0.5s" : "2s"} 
                        repeatCount="indefinite"
                        path={`M${src.x},${src.y} L${tgt.x},${tgt.y}`}
                      />
                    </circle>
                  )}
                </g>
              );
            })}

            {/* Nodes */}
            {nodes.map(node => {
              const isSelected = selectedNodeId === node.id;
              const isBlast = blastSet.has(node.id);
              // Dim unrelated nodes
              const isDimmed = selectedNodeId && !isBlast;

              const color = node.status === 'risk' ? '#ef4444' : getCategoryColor(node.data.category);
              const Icon = getCategoryIcon(node.data.category);

              return (
                <g 
                  key={node.id} 
                  data-node-id={node.id}
                  transform={`translate(${node.x}, ${node.y})`}
                  className={`pointer-events-auto cursor-pointer transition-all duration-300 ${isDimmed ? 'opacity-20' : 'opacity-100'}`}
                >
                  {/* Interaction Hit Area (Larger than visual) */}
                  <circle r="30" fill="transparent" />

                  {/* Blast Ripple / Risk Ripple */}
                  {(isBlast || node.status === 'risk') && !isDimmed && (
                    <circle r="40" className="animate-ping opacity-20" fill={node.status === 'risk' ? '#ef4444' : '#3b82f6'} />
                  )}

                  {/* Node Body */}
                  <circle r="24" fill="#0f172a" stroke={isSelected ? '#fff' : color} strokeWidth={isSelected ? 3 : 2} className="transition-all" />

                  {/* Icon */}
                  <foreignObject x="-12" y="-12" width="24" height="24" className="pointer-events-none">
                    <div className="flex items-center justify-center w-full h-full text-white">
                      <Icon size={14} color={isSelected ? '#fff' : color} />
                    </div>
                  </foreignObject>

                  {/* Label */}
                  <text y="40" textAnchor="middle" fill={isSelected ? '#fff' : '#64748b'} fontSize="10" fontWeight="bold" className="uppercase tracking-widest pointer-events-none select-none">
                    {node.data.label}
                  </text>

                  {/* Risk Badge */}
                  {node.status === 'risk' && (
                    <g transform="translate(16, -16)">
                      <circle r="8" fill="#ef4444" />
                      <text x="0" y="3" textAnchor="middle" fill="white" fontSize="8" fontWeight="bold">!</text>
                    </g>
                  )}
                </g>
              );
            })}
          </g>
        </svg>

        {/* Selected Node Inspector Panel */}
        {selectedNodeData && (
          <div className="absolute top-24 right-8 w-80 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-[32px] p-6 shadow-2xl animate-in slide-in-from-right-10 duration-300 z-30 pointer-events-auto">
             <div className="flex justify-between items-start mb-6">
                <div className={`p-3 rounded-2xl ${selectedNodeData.status === 'risk' ? 'bg-red-500/10 text-red-500' : 'bg-primary-500/10 text-primary-500'}`}>
                   {React.createElement(getCategoryIcon(selectedNodeData.data.category), { size: 24 })}
                </div>
                <button onClick={() => setSelectedNodeId(null)} className="p-2 hover:bg-white/5 rounded-xl text-slate-500 hover:text-white"><X size={18}/></button>
             </div>

             <div className="space-y-4">
                <div>
                   <h3 className="text-xl font-black text-white uppercase italic tracking-tighter">{selectedNodeData.data.label}</h3>
                   <span className="text-[10px] font-mono text-slate-500">{selectedNodeData.data.resource_type}</span>
                </div>

                <div className="p-4 bg-black/40 rounded-2xl border border-white/5 space-y-2">
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Connections</span>
                      <span className="text-white">{edges.filter(e => e.source === selectedNodeData.id || e.target === selectedNodeData.id).length}</span>
                   </div>
                   <div className="flex justify-between text-[10px] uppercase font-bold text-slate-500">
                      <span>Blast Radius</span>
                      <span className={blastSet.size > 1 ? "text-red-500" : "text-emerald-500"}>{blastSet.size} Nodes</span>
                   </div>
                </div>

                {selectedNodeVulns.length > 0 ? (
                   <div className="space-y-2">
                      <h4 className="text-[10px] font-black text-red-500 uppercase tracking-widest flex items-center gap-2">
                         <ShieldAlert size={12} /> Active Vulnerabilities
                      </h4>
                      {selectedNodeVulns.map(v => (
                         <div key={v.id} className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl">
                            <p className="text-[10px] font-bold text-red-400 leading-tight">{v.title}</p>
                         </div>
                      ))}
                   </div>
                ) : (
                   <div className="flex items-center gap-2 text-emerald-500 bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/20">
                      <ShieldAlert size={16} />
                      <span className="text-[10px] font-black uppercase">Secure Resource</span>
                   </div>
                )}

                <button className="w-full py-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-[10px] font-black text-white uppercase tracking-widest transition-all">
                   View HCL Definition
                </button>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { Vulnerability, TimelineEvent, SecurityScore, Severity, ScanStatus, Policy, DriftItem, Guardrail, Asset, ThreatData } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const LATENCY = 800;

// Helper to strip Markdown code blocks from AI response before parsing
const cleanJson = (text: string | undefined): string => {
  if (!text) return '{}';
  // Remove markdown code blocks (```json ... ``` or just ``` ... ```)
  return text.replace(/```json\n?|\n?```/g, '').replace(/```/g, '').trim();
};

class CloudGuardianBackend {
  private db = {
    get: (key: string) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || '[]'),
    set: (key: string, val: any) => localStorage.setItem(`cg_db_${key}`, JSON.stringify(val)),
    getSingle: (key: string, def: any) => JSON.parse(localStorage.getItem(`cg_db_${key}`) || JSON.stringify(def))
  };

  async getGlobalThreats(): Promise<ThreatData[]> {
    return [
      { id: 't-1', type: 'Exploit', region: 'us-east-1', intensity: 85, targets: ['S3', 'IAM'], timestamp: new Date().toISOString() },
      { id: 't-2', type: 'Botnet', region: 'eu-west-1', intensity: 45, targets: ['EC2'], timestamp: new Date().toISOString() },
      { id: 't-3', type: 'Leak', region: 'sa-east-1', intensity: 92, targets: ['RDS'], timestamp: new Date().toISOString() },
      { id: 't-4', type: 'DDoS', region: 'ap-southeast-1', intensity: 20, targets: ['CloudFront'], timestamp: new Date().toISOString() }
    ];
  }

  async getAssets(): Promise<Asset[]> {
    const current = this.db.get('assets');
    if (!current || current.length === 0) {
      const initial: Asset[] = [
        { id: 'as-1', name: 'prod-api-server', type: 'aws_instance', category: 'compute', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 12, cost: 45.5, tags: { env: 'prod' } },
        { id: 'as-2', name: 'customer-data-bucket', type: 'aws_s3_bucket', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 85, cost: 120.0, tags: { env: 'prod', data: 'sensitive' } },
        { id: 'as-3', name: 'auth-db-primary', type: 'aws_db_instance', category: 'storage', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 45, cost: 240.0, tags: { env: 'prod' } },
        { id: 'as-4', name: 'edge-gateway-main', type: 'aws_api_gateway', category: 'network', provider: 'AWS', region: 'us-east-1', status: 'running', riskScore: 5, cost: 15.2, tags: { env: 'prod' } }
      ];
      this.db.set('assets', initial);
      return initial;
    }
    return current;
  }

  async analyzeThreatImpact(threat: ThreatData, assets: Asset[]) {
    const model = 'gemini-3-pro-preview';
    const prompt = `
      You are a Cloud Threat Intelligence Analyst (Sentinel Engine). 

      Task: Correlate this global threat against our asset inventory to identify potential victims.

      Threat Intel:
      ${JSON.stringify(threat)}

      Asset Inventory:
      ${JSON.stringify(assets)}

      Analysis Rules:
      1. Match Assets in the same 'region'.
      2. Match Assets where 'type' or 'category' aligns with threat 'targets'.
      3. Generate a specific tactical recommendation.

      Return JSON:
      {
        "vulnerableCount": number,
        "resources": [Array of vulnerable Asset objects],
        "recommendation": "Specific tactical recommendation string"
      }
    `;
    try {
        const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
        return JSON.parse(cleanJson(resp.text) || '{}');
    } catch (e) {
        console.error("AI Analysis Failed", e);
        // Fallback logic
        const affected = assets.filter(a => a.region === threat.region && threat.targets.some(t => a.type.toLowerCase().includes(t.toLowerCase()) || a.category.toLowerCase().includes(t.toLowerCase())));
        return {
            vulnerableCount: affected.length,
            resources: affected,
            recommendation: `Manual correlation detected ${affected.length} assets in ${threat.region} matching threat profile targets (${threat.targets.join(', ')}). Isolate immediately.`
        };
    }
  }

  async createRemediationPR(vulnId: string, fixCode: string): Promise<{ prUrl: string; branch: string }> {
    await new Promise(r => setTimeout(r, 1500)); // Simulando latência de Git
    const branchName = `fix/security-remediation-${vulnId.slice(-4)}`;

    // Logar no audit trail
    await this.logEvent({
      type: 'PR',
      title: 'Pull Request Aberto',
      description: `Auto-Remediação IA: Corrigindo vulnerabilidade ${vulnId}. Branch: ${branchName}`,
      severity: Severity.LOW
    });

    return {
      prUrl: `https://github.com/org/infra/pull/${Math.floor(Math.random() * 1000)}`,
      branch: branchName
    };
  }

  async getThreatBriefing(): Promise<{ title: string, description: string, severity: Severity }[]> {
    const model = 'gemini-3-flash-preview';
    const prompt = `You are a Global Cyber Threat Intel Analyst. 
    Provide 3 hypothetical but realistic global cloud security news items for today. 
    Format: JSON array of {title, description, severity (HIGH/MEDIUM/LOW)}. Keep it very concise.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(cleanJson(resp.text) || '[]');
    } catch (e) {
      return [{ title: "Credential Leak Pattern", description: "Increase in AWS IAM abuse detected globally.", severity: Severity.HIGH }];
    }
  }

  async suggestFix(vulnerability: string, codeContext: string): Promise<string> {
    const model = 'gemini-3-pro-preview';
    const prompt = `Provide a Terraform HCL code snippet to fix the following vulnerability: "${vulnerability}". Context: \`\`\`hcl\n${codeContext}\n\`\`\` Return only the corrected HCL code block.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt });
      return resp.text || "/* AI Fix unavailable */";
    } catch (e) { return "/* Error generating fix suggestion */"; }
  }

  async generateDefensiveTactics(title: string, resource: string): Promise<any[]> {
    const model = 'gemini-3-pro-preview';
    const prompt = `You are a DevSecOps Security Responder. An incident has occurred: "${title}" on resource "${resource}". Generate 4 immediate tactical containment actions. Return JSON array of { id, title, desc }.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(cleanJson(resp.text) || '[]');
    } catch (e) { return []; }
  }

  async generateRootCauseAnalysis(incident: Vulnerability): Promise<any> {
    const model = 'gemini-3-pro-preview';
    const prompt = `Perform a forensic Root Cause Analysis for this incident: ${JSON.stringify(incident)}. Return JSON: { summary, rootCause, prevention (array), auditEvidenceHash }.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(cleanJson(resp.text) || '{}');
    } catch (e) { return {}; }
  }

  async getGuardrails() {
    const current = this.db.get('guardrails');
    if (!current || current.length === 0) {
      const initial: Guardrail[] = [
        { id: 'gr-1', name: 'S3 Public Block', description: 'Impedir buckets públicos.', resourceType: 'aws_s3_bucket', logic: 'acl != "public-read"', severity: Severity.CRITICAL, status: 'enabled' }
      ];
      this.db.set('guardrails', initial);
      return initial;
    }
    return current;
  }

  async saveGuardrail(gr: Guardrail) {
    const current = this.db.get('guardrails');
    this.db.set('guardrails', [gr, ...current]);
    return true;
  }

  async fetchCloudDrifts() { return this.db.get('drifts'); }
  async resolveDrift(id: string) {
    const drifts = this.db.get('drifts');
    this.db.set('drifts', drifts.filter((d: DriftItem) => d.id !== id));
    return true;
  }

  async getScanHistory() {
    return this.db.get('scan_history');
  }

  async scanInfrastructure(code: string): Promise<{ vulns: Vulnerability[], score: SecurityScore }> {
    await new Promise(r => setTimeout(r, LATENCY));
    const activeGuardrails = (await this.getGuardrails()).filter(g => g.status === 'enabled');
    const model = 'gemini-3-pro-preview';
    const prompt = `Audit the HCL for flaws and violations of: ${activeGuardrails.map(g => `- [${g.severity}] ${g.name}`).join('\n')}. Return JSON: { "findings": [...] }`;
    try {
      const response = await ai.models.generateContent({ model, contents: prompt + "\n\nCode:\n" + code, config: { responseMimeType: "application/json" } });
      // Uses cleanJson to ensure robustness against AI markdown responses
      const findings = JSON.parse(cleanJson(response.text) || '{}').findings || [];
      const vulns = findings.map((f: any, i: number) => ({ ...f, id: `v-${Date.now()}-${i}`, status: ScanStatus.OPEN }));
      const score = this.calculateScore(vulns, this.db.get('drifts'));
      this.db.set('vulnerabilities', vulns);

      const scanRecord = {
        id: `scan-${Date.now()}`,
        timestamp: new Date().toISOString(),
        score: score.total
      };
      const history = this.db.get('scan_history');
      this.db.set('scan_history', [scanRecord, ...history].slice(0, 10));

      return { vulns, score };
    } catch (e) { return { vulns: [], score: this.calculateScore([], []) }; }
  }

  calculateScore(vulns: Vulnerability[], drifts: DriftItem[]): SecurityScore {
    const openVulns = vulns.filter(v => v.status !== ScanStatus.RESOLVED);
    const criticals = openVulns.filter(v => v.severity === Severity.CRITICAL).length + drifts.filter(d => d.severity === Severity.CRITICAL).length;
    const highs = openVulns.filter(v => v.severity === Severity.HIGH).length + drifts.filter(d => d.severity === Severity.HIGH).length;
    const infraBase = Math.max(0, 100 - (criticals * 20) - (highs * 10));
    return { total: infraBase, infrastructure: infraBase, secrets: 100, compliance: Math.max(0, infraBase - 5), drift: drifts.length === 0 ? 100 : 70, finops: 100, trend: 0 };
  }

  async generateAssetInsights(assets: Asset[]) {
    const model = 'gemini-3-pro-preview';
    const prompt = `Analyze this cloud inventory: ${JSON.stringify(assets)}. Identify 3 critical security or cost insights. Return JSON array of {title, impact, recommendation}.`;
    try {
      const resp = await ai.models.generateContent({ model, contents: prompt, config: { responseMimeType: "application/json" } });
      return JSON.parse(cleanJson(resp.text) || '[]');
    } catch (e) { return []; }
  }

  async getVulnerabilities() { return this.db.get('vulnerabilities'); }
  async setVulnerabilities(vulns: Vulnerability[]) { this.db.set('vulnerabilities', vulns); }
  async getTimeline() { return this.db.get('timeline'); }
  async getPolicies() { return this.db.get('policies'); }
  async logEvent(event: any) {
    const timeline = this.db.get('timeline');
    const newEvent = { ...event, id: `evt-${Date.now()}`, timestamp: new Date().toISOString() };
    this.db.set('timeline', [newEvent, ...timeline].slice(0, 50));
    return newEvent;
  }
  async getSystemSettings() { return this.db.getSingle('settings', { accessKeyId: 'AKIA...', region: 'us-east-1', notifications: { autoFix: true, driftSync: false, soc2Logging: true } }); }
  async saveSystemSettings(settings: any) { this.db.set('settings', settings); return true; }
  async getSubscriptionStatus() { return this.db.getSingle('subscription', { tier: 'pro', expires: '2026-12-31', currency: 'USD' }); }
  async upgradeToPro(isPro: boolean) { const sub = { tier: isPro ? 'pro' : 'team', expires: '2026-12-31', currency: 'USD' }; this.db.set('subscription', sub); return sub; }

  // --- NEW: Free Tier Quota Monitor ---
  async getQuotaUsage() {
    // Simulates fetching usage data from connected APIs (Supabase, Clerk, Vercel)
    await new Promise(r => setTimeout(r, 600));
    return {
        database: { used: 125, limit: 500, unit: 'MB', provider: 'Supabase' },
        auth: { used: 850, limit: 10000, unit: 'MAUs', provider: 'Clerk' },
        compute: { used: 32, limit: 100, unit: 'k/req', provider: 'Vercel' },
        storage: { used: 1.2, limit: 10, unit: 'GB', provider: 'R2' }
    };
  }
}

