export const SentinelMap: React.FC = () => {
  const [threats, setThreats] = useState<ThreatData[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedThreat, setSelectedThreat] = useState<ThreatData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResult, setAnalysisResult] = useState<any | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const [t, a] = await Promise.all([API.getGlobalThreats(), API.getAssets()]);
    setThreats(t);
    setAssets(a);
    setLoading(false);
  };

  const handleAnalyzeImpact = async () => {
    if (!selectedThreat) return;
    setIsAnalyzing(true);
    setAnalysisResult(null);

    try {
        // Now calling real AI correlation engine
        const result = await API.analyzeThreatImpact(selectedThreat, assets);
        setAnalysisResult(result);
    } catch (e) {
        console.error("Analysis Error", e);
    } finally {
        setIsAnalyzing(false);
    }
  };

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10 animate-in fade-in duration-700 pb-32 relative">

      {/* Analysis Overlay HUD */}
      {isAnalyzing && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/80 backdrop-blur-md animate-in fade-in">
