               <span className="text-emerald-500 animate-pulse">Audit Ready</span>
            </div>
            <div className="p-3 bg-slate-900 border border-white/5 rounded-xl space-y-2 relative overflow-hidden">
               {/* Scan line animation */}
               <div className="absolute top-0 left-0 w-full h-[1px] bg-emerald-500/50 animate-[scan_3s_linear_infinite]"></div>

               <div className="flex items-center justify-between text-[9px] font-bold text-slate-400">
