// --- Neural Network Monitor Canvas Component ---
const NeuralMonitor = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = canvas.offsetWidth;
    let height = canvas.offsetHeight;
    canvas.width = width;
    canvas.height = height;

    const nodes: any[] = [];
    const particles: any[] = [];

    // Create Nodes
    for (let i = 0; i < 15; i++) {
      nodes.push({
        x: Math.random() * width,
        y: Math.random() * height,
        radius: Math.random() * 3 + 2,
        vx: (Math.random() - 0.5) * 0.5,
        vy: (Math.random() - 0.5) * 0.5,
        isHub: i === 0
      });
    }
    // Center Hub
    nodes[0].x = width / 2;
    nodes[0].y = height / 2;
    nodes[0].radius = 8;
    nodes[0].vx = 0;
    nodes[0].vy = 0;

    const draw = () => {
      ctx.clearRect(0, 0, width, height);

      // Update Nodes
      nodes.forEach(node => {
        if (!node.isHub) {
          node.x += node.vx;
          node.y += node.vy;
          if (node.x < 0 || node.x > width) node.vx *= -1;
          if (node.y < 0 || node.y > height) node.vy *= -1;
        }

        // Draw Node
        ctx.beginPath();
        ctx.arc(node.x, node.y, node.radius, 0, Math.PI * 2);
        ctx.fillStyle = node.isHub ? '#3b82f6' : '#64748b';
        ctx.fill();

        // Glow
        if (node.isHub) {
           ctx.shadowBlur = 20;
           ctx.shadowColor = '#3b82f6';
        } else {
           ctx.shadowBlur = 0;
        }
      });

      // Draw Connections & Spawn Particles
      ctx.shadowBlur = 0;
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const dx = nodes[i].x - nodes[j].x;
          const dy = nodes[i].y - nodes[j].y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < 150) {
            ctx.beginPath();
            ctx.moveTo(nodes[i].x, nodes[i].y);
            ctx.lineTo(nodes[j].x, nodes[j].y);
            ctx.strokeStyle = `rgba(59, 130, 246, ${1 - dist / 150})`;
            ctx.lineWidth = 1;
            ctx.stroke();

            // Randomly spawn particle
            if (Math.random() < 0.005) {
               particles.push({
                  x: nodes[i].x,
                  y: nodes[i].y,
                  tx: nodes[j].x,
                  ty: nodes[j].y,
                  progress: 0,
                  speed: 0.02 + Math.random() * 0.03,
                  isAttack: Math.random() > 0.95
               });
            }
          }
        }
      }

      // Update & Draw Particles
      for (let i = particles.length - 1; i >= 0; i--) {
         const p = particles[i];
         p.progress += p.speed;

         const curX = p.x + (p.tx - p.x) * p.progress;
         const curY = p.y + (p.ty - p.y) * p.progress;

         ctx.beginPath();
         ctx.arc(curX, curY, p.isAttack ? 3 : 1.5, 0, Math.PI * 2);
         ctx.fillStyle = p.isAttack ? '#ef4444' : '#10b981';
         ctx.fill();

         if (p.progress >= 1) particles.splice(i, 1);
      }

      requestAnimationFrame(draw);
    };

    const animId = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animId);
  }, []);

  return <canvas ref={canvasRef} className="w-full h-full opacity-80" />;
};

import { Vulnerability, Severity, ScanStatus, ComplianceControl, GraphNode, GraphEdge, DriftItem, SecurityScore } from '../types';

export const calculateSecurityScore = (findings: Vulnerability[], drifts: DriftItem[]): SecurityScore => {
  let infraBase = 100;
  let secretBase = 100;
  let driftBase = 100;
  let finopsBase = 100;

  findings.forEach(f => {
    const penalty = f.severity === Severity.CRITICAL ? 25 : f.severity === Severity.HIGH ? 15 : 5;
    if (f.ruleId.includes('SECRET')) secretBase -= penalty;
    else if (f.type === 'finops') finopsBase -= penalty;
    else infraBase -= penalty;
  });

  drifts.forEach(d => {
    const penalty = d.severity === Severity.CRITICAL ? 20 : 10;
    driftBase -= penalty;
  });

  infraBase = Math.max(0, infraBase);
  secretBase = Math.max(0, secretBase);
  driftBase = Math.max(0, driftBase);
  finopsBase = Math.max(0, finopsBase);

  const complianceBase = Math.round((infraBase + secretBase + driftBase) / 3);
  const total = Math.round((infraBase * 0.3) + (secretBase * 0.2) + (driftBase * 0.2) + (complianceBase * 0.1) + (finopsBase * 0.2));

  return {
    total,
    infrastructure: infraBase,
    secrets: secretBase,
    compliance: complianceBase,
    drift: driftBase,
    finops: finopsBase,
    trend: total > 70 ? +1.2 : -0.5
  };
};

