export const Architect: React.FC<ArchitectProps> = ({ onApplyCode, onNotify }) => {
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedCode, setGeneratedCode] = useState('');
  const [components, setComponents] = useState<GeneratedComponent[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);
  const intervalRef = useRef<number | null>(null);

  // Cleanup interval on unmount
  useEffect(() => {
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  const cleanJson = (text: string): string => {
    return text.replace(/```json\n?|\n?```/g, '').replace(/```/g, '').trim();
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt.trim()) return;

    // Stop any existing generation to prevent race conditions (letters out of order)
    if (intervalRef.current) clearInterval(intervalRef.current);

    setIsGenerating(true);
    setGeneratedCode('');
    setComponents([]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Parallel generation: Code + Structure
      const [codeResp, structResp] = await Promise.all([
        ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `Generate Terraform HCL code for the following request: "${prompt}". 
          Ensure it follows security best practices (no 0.0.0.0/0, encrypted storage). 
