                 <textarea 
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder="Ex: Crie uma arquitetura AWS para um app React com S3, CloudFront e backend Lambda com DynamoDB..."
                    className="w-full bg-slate-950 border border-slate-800 rounded-3xl p-6 text-sm text-white focus:outline-none focus:border-primary-500 resize-none h-32 shadow-inner leading-relaxed custom-scrollbar"
                    onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) handleGenerate(e); }}
