// --- Holographic 3D Globe Component (The "Senior Engineer" Touch) ---
const HolographicGlobe = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = canvas.offsetWidth;
    let height = canvas.offsetHeight;

    // Handle Retina Display
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);

    // Simulation Constants
    const GLOBE_RADIUS = 180;
    const DOT_COUNT = 400;
    const ROTATION_SPEED = 0.002;
    const dots: {x: number, y: number, z: number, lat: number, lon: number}[] = [];

    // Initialize Dots on Sphere Surface
    for (let i = 0; i < DOT_COUNT; i++) {
        const phi = Math.acos(-1 + (2 * i) / DOT_COUNT);
        const theta = Math.sqrt(DOT_COUNT * Math.PI) * phi;
        dots.push({
            x: GLOBE_RADIUS * Math.cos(theta) * Math.sin(phi),
            y: GLOBE_RADIUS * Math.sin(theta) * Math.sin(phi),
            z: GLOBE_RADIUS * Math.cos(phi),
            lat: phi,
            lon: theta
        });
    }

    let angle = 0;

    const render = () => {
        ctx.clearRect(0, 0, width, height);
        const cx = width / 2;
        const cy = height / 2;

        angle += ROTATION_SPEED;

        // Project and Draw Dots
        dots.forEach(dot => {
            // Rotate around Y axis
            const x = dot.x * Math.cos(angle) - dot.z * Math.sin(angle);
            const z = dot.z * Math.cos(angle) + dot.x * Math.sin(angle);
            const y = dot.y;

            // Perspective projection
            const scale = 300 / (300 + z); 
            const px = cx + x * scale;
            const py = cy + y * scale;

            // Depth modulation
            const alpha = Math.max(0.1, (scale - 0.5) * 1.5); 
            const size = Math.max(0.5, scale * 2);

            // Draw Node
            ctx.beginPath();
            ctx.arc(px, py, size, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(59, 130, 246, ${alpha})`; // Primary Blue

            // Highlight random nodes as "active"
            if (Math.random() > 0.995 && z > 0) {
               ctx.fillStyle = '#ef4444'; // Red Alert
               ctx.shadowBlur = 10;
               ctx.shadowColor = '#ef4444';
            } else {
               ctx.shadowBlur = 0;
            }

            ctx.fill();

            // Draw Connections (Mesh) if close
            if (z > 0) { // Only draw front connections
               dots.forEach(other => {
                   const ox = other.x * Math.cos(angle) - other.z * Math.sin(angle);
                   const oz = other.z * Math.cos(angle) + other.x * Math.sin(angle);
                   const oy = other.y;

                   // Very simple distance check in 3D space before projection
                   const dist = Math.sqrt(Math.pow(x - ox, 2) + Math.pow(y - oy, 2) + Math.pow(z - oz, 2));
                   if (dist < 35 && oz > 0) {
                       const oScale = 300 / (300 + oz);
                       const opx = cx + ox * oScale;
                       const opy = cy + oy * oScale;

                       ctx.beginPath();
                       ctx.moveTo(px, py);
                       ctx.lineTo(opx, opy);
                       ctx.strokeStyle = `rgba(59, 130, 246, ${0.1 * alpha})`;
                       ctx.lineWidth = 0.5;
                       ctx.stroke();
                   }
               });
            }
        });

        // Draw "Atmosphere" Glow
        const gradient = ctx.createRadialGradient(cx, cy, GLOBE_RADIUS * 0.8, cx, cy, GLOBE_RADIUS * 1.2);
        gradient.addColorStop(0, 'rgba(59, 130, 246, 0)');
        gradient.addColorStop(1, 'rgba(59, 130, 246, 0.05)');
        ctx.fillStyle = gradient;
        ctx.beginPath();
        ctx.arc(cx, cy, GLOBE_RADIUS * 1.2, 0, Math.PI * 2);
        ctx.fill();

        requestAnimationFrame(render);
    };

    render();
  }, []);

  return <canvas ref={canvasRef} className="w-full h-full" />;
};

