// --- Optimized Globe Component ---
const HolographicGlobe = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let width = 0;
    let height = 0;

    const resize = () => {
        width = container.offsetWidth;
        height = container.offsetHeight;
        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
    };

    // Observer for container resize (better than window resize)
    const observer = new ResizeObserver(resize);
    observer.observe(container);
    resize();

    // Globe Logic
    const GLOBE_RADIUS = 160;
    const DOT_COUNT = 350;
    let angle = 0;
    const dots: {x: number, y: number, z: number}[] = [];

    // Fibonacci Sphere Distribution
    const phi = Math.PI * (3 - Math.sqrt(5)); 
    for (let i = 0; i < DOT_COUNT; i++) {
        const y = 1 - (i / (DOT_COUNT - 1)) * 2; 
        const radius = Math.sqrt(1 - y * y);
        const theta = phi * i;
        const x = Math.cos(theta) * radius;
        const z = Math.sin(theta) * radius;
        dots.push({ x: x * GLOBE_RADIUS, y: y * GLOBE_RADIUS, z: z * GLOBE_RADIUS });
    }

    const render = () => {
        ctx.clearRect(0, 0, width, height);
        const cx = width / 2;
        const cy = height / 2;
        angle += 0.003;

        // Sort dots by depth for correct occlusion
        const projectedDots = dots.map(dot => {
            // Rotate Y
            const x = dot.x * Math.cos(angle) - dot.z * Math.sin(angle);
            const z = dot.z * Math.cos(angle) + dot.x * Math.sin(angle);
            const y = dot.y;

            // Project
            const scale = 400 / (400 + z);
            const alpha = Math.max(0.1, (scale - 0.4) * 1.5);
            return { x: cx + x * scale, y: cy + y * scale, z, alpha, scale };
        });

        // Draw connections first (background)
        ctx.beginPath();
        ctx.strokeStyle = 'rgba(59, 130, 246, 0.1)';
        ctx.lineWidth = 0.5;
        for (let i = 0; i < projectedDots.length; i++) {
            const p1 = projectedDots[i];
            if (p1.z < 0) continue; // optimization
            for (let j = i + 1; j < projectedDots.length; j++) {
                const p2 = projectedDots[j];
                const dx = p1.x - p2.x;
                const dy = p1.y - p2.y;
                const dist = dx*dx + dy*dy;
                if (dist < 1500) { // Max connection distance squared
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                }
            }
        }
        ctx.stroke();

        // Draw dots
        projectedDots.forEach(p => {
            ctx.beginPath();
            const size = Math.max(0.5, p.scale * 1.5);
            ctx.fillStyle = `rgba(59, 130, 246, ${p.alpha})`; // Blue

            // Random red alert dots
            if (Math.random() > 0.992) {
               ctx.fillStyle = `rgba(239, 68, 68, ${p.alpha})`; // Red
               ctx.shadowBlur = 5;
               ctx.shadowColor = '#ef4444';
            } else {
               ctx.shadowBlur = 0;
            }

            ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
            ctx.fill();
        });

        animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
        observer.disconnect();
        cancelAnimationFrame(animationId);
    };
  }, []);

  return <div ref={containerRef} className="w-full h-full"><canvas ref={canvasRef} className="w-full h-full block" /></div>;
};

