// --- Optimized Globe Component (With Rotation Fix) ---
const HolographicGlobe = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationId: number;
    let width = 0;
    let height = 0;

    const resize = () => {
        width = container.offsetWidth;
        height = container.offsetHeight;
        const dpr = window.devicePixelRatio || 1;
        canvas.width = width * dpr;
        canvas.height = height * dpr;
        ctx.scale(dpr, dpr);
    };

    const observer = new ResizeObserver(resize);
    observer.observe(container);
    resize();

    const GLOBE_RADIUS = 220; // Bigger
    const DOT_COUNT = 500;
    let angle = 0;
    const dots: {x: number, y: number, z: number}[] = [];

    // Fibonacci Sphere
    const phi = Math.PI * (3 - Math.sqrt(5)); 
    for (let i = 0; i < DOT_COUNT; i++) {
        const y = 1 - (i / (DOT_COUNT - 1)) * 2; 
        const radius = Math.sqrt(1 - y * y);
        const theta = phi * i;
        const x = Math.cos(theta) * radius;
        const z = Math.sin(theta) * radius;
        dots.push({ x: x * GLOBE_RADIUS, y: y * GLOBE_RADIUS, z: z * GLOBE_RADIUS });
    }

    const render = () => {
        ctx.clearRect(0, 0, width, height);
        const cx = width / 2;
        const cy = height / 2;
        angle += 0.002; // Slower, majestic rotation

        // Background Ring
        ctx.beginPath();
        ctx.arc(cx, cy, GLOBE_RADIUS + 40, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(59, 130, 246, 0.05)';
        ctx.stroke();

        const projectedDots = dots.map(dot => {
            const x = dot.x * Math.cos(angle) - dot.z * Math.sin(angle);
            const z = dot.z * Math.cos(angle) + dot.x * Math.sin(angle);
            const y = dot.y;
            const scale = 400 / (400 + z);
            const alpha = Math.max(0.1, (scale - 0.4) * 2); // Sharper falloff
            return { x: cx + x * scale, y: cy + y * scale, z, alpha, scale };
        });

        // Connections
        ctx.beginPath();
        ctx.strokeStyle = 'rgba(59, 130, 246, 0.08)'; // Very faint lines
        ctx.lineWidth = 0.5;
        for (let i = 0; i < projectedDots.length; i++) {
            const p1 = projectedDots[i];
            if (p1.z < 0) continue; 
            // Draw connections only to nearest neighbors (simplified)
            for (let j = i + 1; j < Math.min(i + 8, projectedDots.length); j++) {
                const p2 = projectedDots[j];
                const dx = p1.x - p2.x;
                const dy = p1.y - p2.y;
                const dist = dx*dx + dy*dy;
                if (dist < 1800) {
                    ctx.moveTo(p1.x, p1.y);
                    ctx.lineTo(p2.x, p2.y);
                }
            }
        }
        ctx.stroke();

        // Dots
        projectedDots.forEach(p => {
            const isBack = p.z < 0;
            ctx.beginPath();
            // Larger active dots
            const size = isBack ? 0.8 : Math.max(1, p.scale * 2);
            ctx.fillStyle = isBack ? `rgba(100, 116, 139, 0.3)` : `rgba(59, 130, 246, ${p.alpha})`; 

            // Occasional red alert dots
            if (Math.random() > 0.997 && !isBack) {
               ctx.fillStyle = '#ef4444';
               ctx.shadowBlur = 8;
               ctx.shadowColor = '#ef4444';
            } else {
               ctx.shadowBlur = 0;
            }

            ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
            ctx.fill();
        });

        animationId = requestAnimationFrame(render);
    };

    render();

    return () => {
        observer.disconnect();
        cancelAnimationFrame(animationId);
    };
  }, []);

  return <div ref={containerRef} className="w-full h-full"><canvas ref={canvasRef} className="w-full h-full block" /></div>;
};

