import axios from 'axios';
import { toast } from 'sonner';

// Default to localhost:8000 if not set, typical for development
const API_BASE_URL = 'http://localhost:8000';

export const apiClient = axios.create({
  baseURL: API_BASE_URL,
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
});

apiClient.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('access_token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    // 401 Handling (Token Expired)
    if (error.response?.status === 401 && !originalRequest._retry) {
      // In a real scenario with Refresh Tokens, we would attempt refresh here.
      // For now, we logout on 401 to ensure security.
      localStorage.removeItem('access_token');
      localStorage.removeItem('user_data');
      if (!window.location.pathname.includes('/login')) {
        window.location.href = '/login'; 
      }
    }

    // Global Error UI Feedback
    const errorMessage = error.response?.data?.detail || error.message || 'An unexpected error occurred';

    // Don't toast on 401 as we redirect, unless it's a login failure
    if (error.response?.status !== 401 || originalRequest.url.includes('/login')) {
       toast.error(errorMessage);
    }

    return Promise.reject(error);
  }
);

import { useState, useCallback } from 'react';
import { apiClient } from '../lib/api/client';
import { User, AuthResponse } from '../types/api';
import { toast } from 'sonner';

export function useAuth() {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem('user_data');
    return stored ? JSON.parse(stored) : null;
  });

  const login = useCallback(async (email: string, password: string) => {
    try {
      const formData = new URLSearchParams();
      // Using generic object to bypass strict typing if LoginRequest isn't perfectly matched for URLSearchParams
      // But FastAPI OAuth2PasswordRequestForm expects form data
      const response = await apiClient.post<AuthResponse>('/api/v1/auth/login', {
        email, 
        password
      });

      const { access_token, user: userData } = response.data;

      localStorage.setItem('access_token', access_token);
      localStorage.setItem('user_data', JSON.stringify(userData));
      setUser(userData);

      toast.success(`Welcome back, ${userData.full_name || 'User'}!`);
      return userData;
    } catch (error) {
      throw error;
    }
  }, []);

  const register = useCallback(async (data: any) => {
    try {
      await apiClient.post('/api/v1/auth/register', data);
      toast.success('Account created! Please login.');
    } catch (error) {
      throw error;
    }
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('user_data');
    localStorage.removeItem('cg_auth'); // Legacy cleanup
    setUser(null);
    toast.info('Logged out successfully');
  }, []);

  return {
    user,
    isAuthenticated: !!user,
    login,
    register,
    logout
  };
}

